export const LESSONS_MAP: Record<string, any> = {"angels":{"id":"angels","part":11,"title":"Angels and Spiritual Beings","subtitle":"Attending to Scripture without building a speculative system","summary":"Hebrews places angels in relation to the Son and describes their service. A responsible introduction keeps the focus on Christ and distinguishes biblical witness from later art and speculation.","readingMinutes":8,"scripture":{"reference":"Hebrews 1:14","text":"Aren’t they all serving spirits, sent out to do service for the sake of those who will inherit salvation?","context":"Read Hebrews 1:1–14. A sequence of scriptural quotations establishes the Son’s distinctive status in comparison with angels.","url":"https://ebible.org/engwebp/HEB01.htm"},"objectives":["Describe the role assigned to angels in Hebrews 1.","Recognize the chapter’s principal focus on the Son.","Distinguish biblical information from artistic and speculative additions."],"essentialQuestions":["What question is Hebrews 1 answering?","What does the passage say about service?","What should be left unknown rather than filled with imagination?"],"sections":[{"id":"angels-section-1","title":"Read the comparison from the beginning","paragraphs":["Hebrews begins with God’s speech through prophets and then through the Son. It describes the Son’s relation to creation, purification, and divine glory before contrasting him with angels. The chapter’s principal purpose is therefore not to satisfy curiosity about an invisible world. It directs attention to the Son’s distinctive identity and work.","The sequence of quotations is important. Individual lines are assembled into an argument, so a study should ask how each contributes to that argument. Verse 14 names angels as serving spirits. That description locates their role in service rather than making them rivals to the Son or independent sources of salvation."],"claimIds":["angels-1-1","angels-1-2"]},{"id":"angels-section-2","title":"Service rather than fascination","paragraphs":["A reader may reasonably ask about angelic appearances elsewhere in Scripture, but this passage does not offer a complete hierarchy, anatomy, or list of names. It does not specify how every instance of angelic service can be recognized in daily experience. Refusing to invent those details is part of learning from the text.","Colossians 1 includes invisible things, thrones, dominions, principalities, and powers within the scope of what is created through and for Christ. The passage’s broad claim is Christ’s preeminence. A speculative chart assigning each expression to a precise cosmic rank would require evidence the paragraph does not supply."],"claimIds":["angels-2-1","angels-2-2"]},{"id":"angels-section-3","title":"The difference between art and evidence","paragraphs":["Christian art depicts spiritual beings in many ways. An illustration can symbolize service, holiness, or proclamation without documenting the physical appearance of a being. Every such image in this project should be labeled as an artist’s interpretation. Visual familiarity does not turn a detail into a verified biblical statement.","The same care applies to stories about protection or an unusual experience. A testimony can be heard respectfully without being certified as proof of a specific angelic intervention. This lesson does not diagnose spiritual causes for illness, distress, or an unexplained event. Appropriate practical and professional help should not be displaced by a speculative explanation."],"claimIds":["angels-3-1","angels-3-2"]},{"id":"angels-section-4","title":"An appropriately modest response","paragraphs":["The lesson’s diagram records a textual order: God speaks through the Son; the Son is distinguished from angels; angels are described in terms of service. This simple visual keeps the argument readable. It is intentionally not a complete map of spiritual reality.","For group discussion, divide proposed claims into three columns: directly stated in the passage, inferred from it, and not established by it. Then ask what ordinary service the community can practice. The application is not that humans are angels; it is that fascination with the unseen should not distract from clear responsibilities toward a neighbor."],"claimIds":["angels-4-1","angels-4-2"]},{"id":"angels-section-5","title":"A claim-by-claim reading exercise","paragraphs":["Take a familiar claim about angels and ask whether either selected passage establishes it. A claim about service has a direct textual locator in Hebrews 1:14. A claim about a specific color of wings or a fixed arrangement of ranks does not follow from that verse. The difference is not hostility to art or tradition; it is an honest account of what evidence is doing.","If the claim belongs to a particular tradition, identify that source and record it under the appropriate category. If it is an artistic choice, label it as such. If no source has been established, leave it as a question. A reader should never have to guess whether a confident sentence comes from Scripture, a church document, or the author’s imagination. This discipline can make a visually rich chapter more trustworthy rather than less engaging. Clear labels help readers enjoy art without confusing its details with doctrine."],"claimIds":["angels-5-1","angels-5-2"]}],"languageNote":{"term":"Angelology","transliteration":"Conventional theological label","meaning":"The doctrinal study of angels and related biblical testimony about spiritual beings.","caution":"A theological label supplies no warrant for a detailed hierarchy. This lesson makes no claim about a Greek word’s meaning apart from the passage’s context.","sourceUrl":"https://ebible.org/engwebp/HEB01.htm"},"relatedPassages":[{"reference":"Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm"},{"reference":"Matthew 28:1–7","url":"https://ebible.org/engwebp/MAT28.htm"}],"consensus":"The Nicene profile confesses God as maker of visible and invisible creation. Hebrews distinguishes the Son from angels and calls angels serving spirits.","disputed":"Guardian-angel traditions, detailed hierarchies, and accounts of contemporary spiritual activity vary. They are not authenticated by this introductory lesson.","application":["Label artistic depictions honestly.","Keep a list of questions the passage does not answer instead of inventing a system."],"reflection":["Does curiosity about the unseen draw me away from a clear responsibility?","Can I respect a testimony without claiming certainty about its explanation?"],"discussion":["How does the opening of Hebrews control the interpretation of verse 14?","Which details in a familiar angel image are actually established by the selected passage?"],"quiz":[{"question":"What is the main comparison in Hebrews 1?","options":["The Son and angels","Two equal creators","A complete list of cosmic ranks"],"answer":0,"explanation":"The chapter emphasizes the Son’s distinctive status and describes angels as servants."},{"question":"How should a symbolic angel illustration be labeled?","options":["A verified anatomical reconstruction","An artist’s interpretation","A new source of doctrine"],"answer":1,"explanation":"Art may support learning, but its details must not be presented as independently verified evidence."}],"sources":[{"id":"hebrews","title":"World English Bible (Updated): Hebrews 1:1–14","url":"https://ebible.org/engwebp/HEB01.htm","locator":"Hebrews 1:1–14","category":"A"},{"id":"colossians","title":"World English Bible (Updated): Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm","locator":"Colossians 1:15–20","category":"A"}],"claims":[{"id":"angels-1-1","text":"Hebrews begins with God’s speech through prophets and then through the Son. It describes the Son’s relation to creation, purification, and divine glory before contrasting him with angels. The chapter’s principal purpose is therefore not to satisfy curiosity about an invisible world. It directs attention to the Son’s distinctive identity and work.","sourceIds":["hebrews"],"locator":"Hebrews 1:1–14","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-1-2","text":"The sequence of quotations is important. Individual lines are assembled into an argument, so a study should ask how each contributes to that argument. Verse 14 names angels as serving spirits. That description locates their role in service rather than making them rivals to the Son or independent sources of salvation.","sourceIds":["hebrews"],"locator":"Hebrews 1:1–14","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-2-1","text":"A reader may reasonably ask about angelic appearances elsewhere in Scripture, but this passage does not offer a complete hierarchy, anatomy, or list of names. It does not specify how every instance of angelic service can be recognized in daily experience. Refusing to invent those details is part of learning from the text.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:14; Colossians 1:15–20; limits on inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-2-2","text":"Colossians 1 includes invisible things, thrones, dominions, principalities, and powers within the scope of what is created through and for Christ. The passage’s broad claim is Christ’s preeminence. A speculative chart assigning each expression to a precise cosmic rank would require evidence the paragraph does not supply.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:14; Colossians 1:15–20; limits on inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-3-1","text":"Christian art depicts spiritual beings in many ways. An illustration can symbolize service, holiness, or proclamation without documenting the physical appearance of a being. Every such image in this project should be labeled as an artist’s interpretation. Visual familiarity does not turn a detail into a verified biblical statement.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:1–14; Colossians 1:15–20; explicit editorial and pastoral boundaries","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-3-2","text":"The same care applies to stories about protection or an unusual experience. A testimony can be heard respectfully without being certified as proof of a specific angelic intervention. This lesson does not diagnose spiritual causes for illness, distress, or an unexplained event. Appropriate practical and professional help should not be displaced by a speculative explanation.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:1–14; Colossians 1:15–20; explicit editorial and pastoral boundaries","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-4-1","text":"The lesson’s diagram records a textual order: God speaks through the Son; the Son is distinguished from angels; angels are described in terms of service. This simple visual keeps the argument readable. It is intentionally not a complete map of spiritual reality.","sourceIds":["hebrews"],"locator":"Hebrews 1:1–14; teaching exercise and application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-4-2","text":"For group discussion, divide proposed claims into three columns: directly stated in the passage, inferred from it, and not established by it. Then ask what ordinary service the community can practice. The application is not that humans are angels; it is that fascination with the unseen should not distract from clear responsibilities toward a neighbor.","sourceIds":["hebrews"],"locator":"Hebrews 1:1–14; teaching exercise and application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-5-1","text":"Take a familiar claim about angels and ask whether either selected passage establishes it. A claim about service has a direct textual locator in Hebrews 1:14. A claim about a specific color of wings or a fixed arrangement of ranks does not follow from that verse. The difference is not hostility to art or tradition; it is an honest account of what evidence is doing.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:1–14; Colossians 1:15–20; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"angels-5-2","text":"If the claim belongs to a particular tradition, identify that source and record it under the appropriate category. If it is an artistic choice, label it as such. If no source has been established, leave it as a question. A reader should never have to guess whether a confident sentence comes from Scripture, a church document, or the author’s imagination. This discipline can make a visually rich chapter more trustworthy rather than less engaging. Clear labels help readers enjoy art without confusing its details with doctrine.","sourceIds":["hebrews","colossians"],"locator":"Hebrews 1:1–14; Colossians 1:15–20; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"The focus of Hebrews 1","steps":["God speaks","The Son revealed","Angels distinguished","Service described"]}},"bread-of-life":{"id":"bread-of-life","part":8,"title":"Jesus, the Bread of Life","subtitle":"The sign points beyond the meal to the giver of life","summary":"John 6 moves from a shared meal to a demanding conversation about Jesus’ identity, faith, flesh, and life. Read the discourse as a whole and identify sacramental differences fairly.","readingMinutes":12,"scripture":{"reference":"John 6:35","text":"Jesus said to them, “I am the bread of life. Whoever comes to me will not be hungry, and whoever believes in me will never be thirsty.","context":"Read John 6:1–71. The discourse follows the feeding of the crowd near Passover, the crossing of the sea, and the crowd’s search for Jesus. The discussion later occurs in the synagogue at Capernaum.","url":"https://ebible.org/engwebp/JHN06.htm"},"objectives":["Trace the movement from the feeding sign to the discourse.","Explain the connection between coming, believing, and receiving life.","Distinguish a textual observation from a sacramental interpretation."],"essentialQuestions":["What does the crowd seek, and how does Jesus redirect its question?","How does the manna comparison function?","Why do Christian traditions read the later flesh-and-blood language differently?"],"sections":[{"id":"bread-of-life-section-1","title":"Read the meal and the discourse together","paragraphs":["John locates the feeding near Passover and portrays Jesus giving thanks before the food is distributed. The crowd recognizes a sign but then seeks to make Jesus king by force. Jesus withdraws. The narrative therefore already distinguishes receiving bread from understanding the giver. It does not portray every response to an impressive event as faithful recognition.","The next day the crowd searches for Jesus. He tells them that their search is connected to having eaten and been filled, then redirects attention toward food that remains to eternal life. This is not contempt for hungry people: the narrative has just described their feeding. The movement is from the gift toward the identity and mission of the giver. A lesson should preserve both the concrete meal and the theological discourse."],"claimIds":["bread-of-life-1-1","bread-of-life-1-2"]},{"id":"bread-of-life-section-2","title":"The manna question and the invitation to believe","paragraphs":["The conversation invokes bread from heaven and the ancestors’ experience of manna. Jesus shifts attention from Moses to the Father as giver and from past food to the true bread giving life to the world. This comparison belongs to Israel’s scriptural story; it should not be treated as though Jesus were inventing an isolated spiritual metaphor without a literary history.","Verse 35 joins coming to Jesus with believing in him. In this setting “bread of life” identifies Jesus as the one through whom life is received. The promise is not a guarantee that a Christian body will never need food or water. Reading literal biological immunity into the sentence would ignore the discourse’s way of speaking about eternal life and resurrection."],"claimIds":["bread-of-life-2-1","bread-of-life-2-2"]},{"id":"bread-of-life-section-3","title":"The gift of flesh and the difficulty of the saying","paragraphs":["The later discourse speaks of Jesus giving his flesh for the life of the world and of eating his flesh and drinking his blood. The language provokes dispute and leads some disciples to call the teaching hard. Its difficulty is part of the narrative, not a problem a teacher should erase by selecting only the most familiar sentence.","Verse 63 says the Spirit gives life and that Jesus’ words are spirit and life. Different traditions understand how this statement relates to the preceding flesh-and-blood language. The text must be read as a sequence, without using one line to dismiss the rest. A group can identify the verbal links before deciding how a confessional interpretation explains them."],"claimIds":["bread-of-life-3-1","bread-of-life-3-2"]},{"id":"bread-of-life-section-4","title":"Sacramental readings must be named","paragraphs":["Catholic teaching on Christian initiation describes the Eucharist as nourishment with Christ’s Body and Blood. The Baptist Faith and Message VII describes the Lord’s Supper with symbolic and memorial language. These are examples of identified confessional positions, not a complete survey of every Catholic, Orthodox, Lutheran, Reformed, Anglican, Baptist, or other Christian account.","This preview does not rule that all readers must understand every verse of John 6 as an exclusive reference to the Eucharist, nor does it rule out sacramental meaning. It records the passage and a genuine interpretive difference. A church adopting the lesson should supply its received teaching and review the terminology before using it for sacramental preparation."],"claimIds":["bread-of-life-4-1","bread-of-life-4-2"]},{"id":"bread-of-life-section-5","title":"Receive the person, not a technique","paragraphs":["At the end of the chapter, many disciples withdraw and Jesus questions the twelve. Peter responds by appealing to the words of eternal life. The narrative ends with trust and a warning concerning betrayal, so it cannot be reduced to a promise of an uncomplicated religious experience. The title “Bread of Life” directs attention to Jesus’ identity and words.","A pastoral application is to ask what one seeks from Jesus: merely a solution to a pressing problem, or a life shaped by receiving his teaching. That question should not belittle material need. A community can study the discourse while sharing actual bread with a neighbor. The meal and the discourse make it especially inappropriate to use spiritual language as an excuse for practical indifference."],"claimIds":["bread-of-life-5-1","bread-of-life-5-2"]}],"languageNote":{"term":"Bread of Life","transliteration":"WEB title in John 6:35","meaning":"A metaphorical self-identification of Jesus within a discourse about receiving life from him.","caution":"This is a contextual explanation, not an argument from an isolated Greek word. Eucharistic interpretations require the whole discourse and an identified theological framework.","sourceUrl":"https://ebible.org/engwebp/JHN06.htm"},"relatedPassages":[{"reference":"John 6:51–58","url":"https://ebible.org/engwebp/JHN06.htm"},{"reference":"James 2:14–17","url":"https://ebible.org/engwebp/JAS02.htm"}],"consensus":"The declared profile identifies Jesus as giver of life. The discourse explicitly links coming and believing with eternal life and resurrection; its full sacramental interpretation is not a consensus claim here.","disputed":"Christians differ over the Eucharistic significance of John 6 and the manner of Christ’s presence in communion. Catholic and Baptist sources illustrate distinct views without exhausting the range of traditions.","application":["Read the full discourse before using verse 35 devotionally.","Pair study with a concrete act of care for someone lacking food.","Use your church’s reviewed sacramental terminology in teaching."],"reflection":["What do I seek when I come to Jesus?","Which difficult part of the discourse do I tend to skip?"],"discussion":["How does the feeding sign prepare the conversation?","Where can different traditions agree on textual observations before debating interpretation?","How can spiritual language and material care remain connected?"],"quiz":[{"question":"What event precedes the discourse?","options":["The feeding of a crowd","The building of a temple","An ascension in Jerusalem"],"answer":0,"explanation":"John 6 begins with the feeding sign and then follows the crowd’s search for Jesus."},{"question":"Which interpretation is inappropriate?","options":["The discourse connects believing with life","Verse 35 guarantees that believers never need physical food","The chapter includes difficult language about flesh and blood"],"answer":1,"explanation":"The discourse concerns Jesus as giver of eternal life; it does not promise biological immunity to hunger."},{"question":"How should sacramental differences be presented?","options":["As though every church has the same account","With named traditions, sources, and review","By removing the difficult verses"],"answer":1,"explanation":"The preview identifies differences and asks a local church to confirm its received teaching."}],"sources":[{"id":"john6","title":"World English Bible (Updated): John 6:1–71","url":"https://ebible.org/engwebp/JHN06.htm","locator":"John 6:1–71","category":"A"},{"id":"james","title":"World English Bible (Updated): James 2:14–17","url":"https://ebible.org/engwebp/JAS02.htm","locator":"James 2:14–17","category":"A"},{"id":"ccc-initiation","title":"Catechism of the Catholic Church: Christian Initiation","url":"https://www.vatican.va/archive/ENG0015/__P3O.HTM","locator":"1275–1284, especially 1275","category":"E"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"}],"claims":[{"id":"bread-of-life-1-1","text":"John locates the feeding near Passover and portrays Jesus giving thanks before the food is distributed. The crowd recognizes a sign but then seeks to make Jesus king by force. Jesus withdraws. The narrative therefore already distinguishes receiving bread from understanding the giver. It does not portray every response to an impressive event as faithful recognition.","sourceIds":["john6"],"locator":"John 6:1–27","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-1-2","text":"The next day the crowd searches for Jesus. He tells them that their search is connected to having eaten and been filled, then redirects attention toward food that remains to eternal life. This is not contempt for hungry people: the narrative has just described their feeding. The movement is from the gift toward the identity and mission of the giver. A lesson should preserve both the concrete meal and the theological discourse.","sourceIds":["john6"],"locator":"John 6:1–27","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-2-1","text":"The conversation invokes bread from heaven and the ancestors’ experience of manna. Jesus shifts attention from Moses to the Father as giver and from past food to the true bread giving life to the world. This comparison belongs to Israel’s scriptural story; it should not be treated as though Jesus were inventing an isolated spiritual metaphor without a literary history.","sourceIds":["john6"],"locator":"John 6:28–40","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-2-2","text":"Verse 35 joins coming to Jesus with believing in him. In this setting “bread of life” identifies Jesus as the one through whom life is received. The promise is not a guarantee that a Christian body will never need food or water. Reading literal biological immunity into the sentence would ignore the discourse’s way of speaking about eternal life and resurrection.","sourceIds":["john6"],"locator":"John 6:28–40","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-3-1","text":"The later discourse speaks of Jesus giving his flesh for the life of the world and of eating his flesh and drinking his blood. The language provokes dispute and leads some disciples to call the teaching hard. Its difficulty is part of the narrative, not a problem a teacher should erase by selecting only the most familiar sentence.","sourceIds":["john6"],"locator":"John 6:48–66","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-3-2","text":"Verse 63 says the Spirit gives life and that Jesus’ words are spirit and life. Different traditions understand how this statement relates to the preceding flesh-and-blood language. The text must be read as a sequence, without using one line to dismiss the rest. A group can identify the verbal links before deciding how a confessional interpretation explains them.","sourceIds":["john6"],"locator":"John 6:48–66","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-4-1","text":"Catholic teaching on Christian initiation describes the Eucharist as nourishment with Christ’s Body and Blood. The Baptist Faith and Message VII describes the Lord’s Supper with symbolic and memorial language. These are examples of identified confessional positions, not a complete survey of every Catholic, Orthodox, Lutheran, Reformed, Anglican, Baptist, or other Christian account.","sourceIds":["john6","ccc-initiation","bfm"],"locator":"John 6:51–58; Catechism 1275; Baptist Faith and Message VII","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-4-2","text":"This preview does not rule that all readers must understand every verse of John 6 as an exclusive reference to the Eucharist, nor does it rule out sacramental meaning. It records the passage and a genuine interpretive difference. A church adopting the lesson should supply its received teaching and review the terminology before using it for sacramental preparation.","sourceIds":["john6","ccc-initiation","bfm"],"locator":"John 6:51–58; Catechism 1275; Baptist Faith and Message VII","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-5-1","text":"At the end of the chapter, many disciples withdraw and Jesus questions the twelve. Peter responds by appealing to the words of eternal life. The narrative ends with trust and a warning concerning betrayal, so it cannot be reduced to a promise of an uncomplicated religious experience. The title “Bread of Life” directs attention to Jesus’ identity and words.","sourceIds":["john6","james"],"locator":"John 6:66–71; James 2:14–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"bread-of-life-5-2","text":"A pastoral application is to ask what one seeks from Jesus: merely a solution to a pressing problem, or a life shaped by receiving his teaching. That question should not belittle material need. A community can study the discourse while sharing actual bread with a neighbor. The meal and the discourse make it especially inappropriate to use spiritual language as an excuse for practical indifference.","sourceIds":["john6","james"],"locator":"John 6:66–71; James 2:14–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"Follow John’s narrative","steps":["A meal shared","The giver sought","The bread of life revealed","A response of faith"]}},"church":{"id":"church","part":12,"title":"The Church: A People Learning Life Together","subtitle":"Teaching, fellowship, bread, prayer, and care","summary":"Acts 2 portrays a community formed around apostolic teaching and shared life. The narrative offers a rich starting point while leaving later questions of polity and sacramental practice for identified traditions.","readingMinutes":9,"scripture":{"reference":"Acts 2:42","text":"They continued steadfastly in the apostles’ teaching and fellowship, in the breaking of bread, and prayer.","context":"Read Acts 2:37–47 after the Pentecost sermon. Those receiving the message are baptized, and the narrative describes their practices and material care.","url":"https://ebible.org/engwebp/ACT02.htm"},"objectives":["Identify the practices named in Acts 2:42–47.","Connect belonging with material care and mutual dependence.","Distinguish narrative description from a complete church constitution."],"essentialQuestions":["What makes the community recognizable in this paragraph?","How are worship and care connected?","Which church questions need additional texts and confessional decisions?"],"sections":[{"id":"church-section-1","title":"A community formed by a message","paragraphs":["Acts 2 places the shared life of the community after Peter’s proclamation concerning Jesus, resurrection, repentance, and baptism. The practices in verse 42 do not appear as a generic strategy for building an appealing club. They belong to a people responding to the message that Luke’s narrative has just reported.","The paragraph names apostolic teaching, fellowship, breaking bread, and prayer. It then describes shared possessions and distribution according to need. Reading to the end prevents “fellowship” from becoming only a pleasant meeting. Material care is visible within the picture of communal life."],"claimIds":["church-1-1","church-1-2"]},{"id":"church-section-2","title":"Belonging and mutual dependence","paragraphs":["First Corinthians 12 offers a companion image: a body with many members. The metaphor rules out the idea that one visible member can dismiss the rest as unnecessary. It does not require everyone to perform the same role. Belonging includes both contributing and receiving, so needing help is not evidence of having no place.","Ephesians 2 adds images of citizenship, household, and a building with Christ as cornerstone. These images help a beginner see why ecclesiology concerns a people rather than merely an institution or building. Each image has its own setting and limits; no single one supplies every detail of organization."],"claimIds":["church-2-1","church-2-2"]},{"id":"church-section-3","title":"Description, pattern, and church decisions","paragraphs":["Acts is a narrative. Its account can shape reflection without being treated as a complete legal code prescribing every detail in every place. Readers should distinguish a description of what happened, an enduring principle inferred from it, and a practical decision for a present congregation. Those are related but separate steps.","The Baptist Faith and Message VI–VII describes Baptist congregational life and ordinances; Westminster XXV and XXVIII provides a Reformed confessional account. The Catholic Catechism’s account of initiation describes a different sacramental framework. Baptism, communion, ordination, and oversight therefore require explicit local doctrinal review. This preview offers a shared study text while identifying that such decisions remain."],"claimIds":["church-3-1","church-3-2"]},{"id":"church-section-4","title":"A community that can be inspected","paragraphs":["A church can ask concrete questions of this portrait: Is teaching understandable? Are prayer and shared meals accessible? Does someone’s need become visible without humiliating them? Are resources distributed fairly? These are applications for discernment rather than a claim that a numerical score can determine whether a congregation is the church.","Choose one improvement small enough to complete: arrange a meal for someone recovering, make a study resource accessible, or establish a clear way to request help. A study of ecclesiology becomes more credible when the vocabulary of body and household is accompanied by actual practices of welcome, care, and accountability."],"claimIds":["church-4-1","church-4-2"]},{"id":"church-section-5","title":"Shared life with accountable practice","paragraphs":["The description of distribution according to need invites attention to how need is recognized. People do not always ask for assistance publicly, and a community may need a respectful process for receiving requests. The passage does not prescribe a modern administrative system; the principle must be worked out through wise, transparent, and appropriate practice.","Similarly, the body metaphor should not become a way to pressure exhausted people into constant unpaid labor. Mutual care includes receiving support and recognizing limits. A ministry plan can be reviewed by asking whether it protects participation, shares burdens, and gives less visible members a voice. These are contemporary applications offered for discussion and pastoral judgment. They should be evaluated with the people affected rather than presented as a complete blueprint dictated by one verse. Keep a record of the decision and invite review when its effect differs from what the group intended."],"claimIds":["church-5-1","church-5-2"]}],"languageNote":{"term":"Ecclesiology","transliteration":"Conventional theological label","meaning":"The doctrinal study of the church and its life.","caution":"The lesson does not infer a complete form of church government from an isolated word. Narrative, letters, and identified traditions all require contextual reading.","sourceUrl":"https://ebible.org/engwebp/ACT02.htm"},"relatedPassages":[{"reference":"1 Corinthians 12:12–26","url":"https://ebible.org/engwebp/1CO12.htm"},{"reference":"Ephesians 2:19–22","url":"https://ebible.org/engwebp/EPH02.htm"}],"consensus":"The Nicene profile confesses the church. The selected passages describe teaching, worship, belonging, and mutual care; they do not erase confessional differences in ministry and sacramental practice.","disputed":"Baptism’s recipients and efficacy, communion, apostolic succession, ordination, and forms of governance differ among traditions. Local choices remain unconfirmed.","application":["Connect a study gathering to a concrete practice of care.","Check whether people can request help without shame or unnecessary disclosure."],"reflection":["What do I receive from the body as well as contribute?","Whose need may be difficult to see in our community?"],"discussion":["Which practices are explicitly named in Acts 2?","How can a church move from a biblical principle to a practical policy transparently?"],"quiz":[{"question":"Which practice appears in Acts 2:42?","options":["A complete modern constitution","The apostles’ teaching","Uniform gifts for everyone"],"answer":1,"explanation":"Acts names teaching, fellowship, breaking bread, and prayer, then describes material care."},{"question":"What does the body metaphor resist?","options":["Mutual dependence","Dismissing another member as unnecessary","Different forms of service"],"answer":1,"explanation":"The body needs its members, including those considered weaker."}],"sources":[{"id":"acts","title":"World English Bible (Updated): Acts 2:22–47","url":"https://ebible.org/engwebp/ACT02.htm","locator":"Acts 2:22–47","category":"A"},{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 12:12–26","url":"https://ebible.org/engwebp/1CO12.htm","locator":"1 Corinthians 12:12–26","category":"A"},{"id":"ephesians","title":"World English Bible (Updated): Ephesians 2:19–22","url":"https://ebible.org/engwebp/EPH02.htm","locator":"Ephesians 2:19–22","category":"A"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"},{"id":"ccc-initiation","title":"Catechism: Christian Initiation","url":"https://www.vatican.va/archive/ENG0015/__P3O.HTM","locator":"1275–1284","category":"E"}],"claims":[{"id":"church-1-1","text":"Acts 2 places the shared life of the community after Peter’s proclamation concerning Jesus, resurrection, repentance, and baptism. The practices in verse 42 do not appear as a generic strategy for building an appealing club. They belong to a people responding to the message that Luke’s narrative has just reported.","sourceIds":["acts"],"locator":"Acts 2:22–47, especially 37–47","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-1-2","text":"The paragraph names apostolic teaching, fellowship, breaking bread, and prayer. It then describes shared possessions and distribution according to need. Reading to the end prevents “fellowship” from becoming only a pleasant meeting. Material care is visible within the picture of communal life.","sourceIds":["acts"],"locator":"Acts 2:22–47, especially 37–47","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-2-1","text":"First Corinthians 12 offers a companion image: a body with many members. The metaphor rules out the idea that one visible member can dismiss the rest as unnecessary. It does not require everyone to perform the same role. Belonging includes both contributing and receiving, so needing help is not evidence of having no place.","sourceIds":["corinthians","ephesians"],"locator":"1 Corinthians 12:12–26; Ephesians 2:19–22","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-2-2","text":"Ephesians 2 adds images of citizenship, household, and a building with Christ as cornerstone. These images help a beginner see why ecclesiology concerns a people rather than merely an institution or building. Each image has its own setting and limits; no single one supplies every detail of organization.","sourceIds":["corinthians","ephesians"],"locator":"1 Corinthians 12:12–26; Ephesians 2:19–22","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-3-1","text":"Acts is a narrative. Its account can shape reflection without being treated as a complete legal code prescribing every detail in every place. Readers should distinguish a description of what happened, an enduring principle inferred from it, and a practical decision for a present congregation. Those are related but separate steps.","sourceIds":["acts","bfm","wcf","ccc-initiation"],"locator":"Acts 2:37–47; Baptist Faith and Message VI–VII; Westminster XXV, XXVIII; Catechism 1275–1284","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-3-2","text":"The Baptist Faith and Message VI–VII describes Baptist congregational life and ordinances; Westminster XXV and XXVIII provides a Reformed confessional account. The Catholic Catechism’s account of initiation describes a different sacramental framework. Baptism, communion, ordination, and oversight therefore require explicit local doctrinal review. This preview offers a shared study text while identifying that such decisions remain.","sourceIds":["acts","bfm","wcf","ccc-initiation"],"locator":"Acts 2:37–47; Baptist Faith and Message VI–VII; Westminster XXV, XXVIII; Catechism 1275–1284","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-4-1","text":"A church can ask concrete questions of this portrait: Is teaching understandable? Are prayer and shared meals accessible? Does someone’s need become visible without humiliating them? Are resources distributed fairly? These are applications for discernment rather than a claim that a numerical score can determine whether a congregation is the church.","sourceIds":["acts","corinthians","ephesians"],"locator":"Acts 2:42–47; 1 Corinthians 12:22–26; Ephesians 2:19; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-4-2","text":"Choose one improvement small enough to complete: arrange a meal for someone recovering, make a study resource accessible, or establish a clear way to request help. A study of ecclesiology becomes more credible when the vocabulary of body and household is accompanied by actual practices of welcome, care, and accountability.","sourceIds":["acts","corinthians","ephesians"],"locator":"Acts 2:42–47; 1 Corinthians 12:22–26; Ephesians 2:19; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-5-1","text":"The description of distribution according to need invites attention to how need is recognized. People do not always ask for assistance publicly, and a community may need a respectful process for receiving requests. The passage does not prescribe a modern administrative system; the principle must be worked out through wise, transparent, and appropriate practice.","sourceIds":["acts","corinthians"],"locator":"Acts 2:42–47; 1 Corinthians 12:22–26; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"church-5-2","text":"Similarly, the body metaphor should not become a way to pressure exhausted people into constant unpaid labor. Mutual care includes receiving support and recognizing limits. A ministry plan can be reviewed by asking whether it protects participation, shares burdens, and gives less visible members a voice. These are contemporary applications offered for discussion and pastoral judgment. They should be evaluated with the people affected rather than presented as a complete blueprint dictated by one verse. Keep a record of the decision and invite review when its effect differs from what the group intended.","sourceIds":["acts","corinthians"],"locator":"Acts 2:42–47; 1 Corinthians 12:22–26; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"cycle","title":"A shared life in Acts 2","steps":["Teaching","Fellowship","Bread and prayer","Care according to need"]}},"creation-covenant":{"id":"creation-covenant","part":5,"title":"Creation, Covenant, and Providence","subtitle":"A good world sustained by a faithful Creator","summary":"Genesis’s account of creation and the covenant with Noah provide a framework for gratitude, responsibility, and hope without making every event easy to explain.","readingMinutes":9,"scripture":{"reference":"Genesis 1:1–2","text":"In the beginning, God created the heavens and the earth. The earth was formless and empty. Darkness was on the surface of the deep and God’s Spirit was hovering over the surface of the waters.","context":"Read Genesis 1:1–31 and Genesis 9:8–17. Creation’s repeated declarations of goodness should be read with the later narrative of judgment and covenant.","url":"https://ebible.org/engwebp/GEN01.htm"},"objectives":["Distinguish creation, covenant, and providence.","Describe the scope of the Noahic covenant in Genesis 9.","Apply creaturely responsibility without claiming certainty about every tragedy."],"essentialQuestions":["What is affirmed when creation is called good?","Who is included in the covenant with Noah?","How can trust coexist with lament?"],"sections":[{"id":"creation-covenant-section-1","title":"The world as gift","paragraphs":["Genesis 1 presents God as creator of the heavens and the earth. Its ordered sequence repeatedly names the goodness of what is made and culminates in a judgment that the whole is very good. The lesson begins with that theological witness. It does not turn a short introduction into a ruling on every scientific or literary question associated with the chapter.","To call the world created is to confess dependence rather than self-sufficiency. Gratitude and responsibility are reasonable applications: food, land, other creatures, and human neighbors are received within a world whose source is God. These are implications drawn for discipleship, not additional sentences that can be inserted into Genesis as verbatim text."],"claimIds":["creation-covenant-1-1","creation-covenant-1-2"]},{"id":"creation-covenant-section-2","title":"Covenant after the flood","paragraphs":["Genesis 9 identifies a covenant with Noah, his descendants, and living creatures. Its sign is the rainbow, and its particular promise concerns the destruction of all flesh by flood. Reading its named parties and stated promise prevents the covenant from becoming an undefined assurance that no painful event will happen again.","Covenant is not simply a synonym for a private bargain. In this narrative the promise is initiated by God and extends beyond Noah’s immediate household. A study group should inspect who speaks, who receives, what is promised, and what sign is named before connecting this covenant to others. Connections with Abraham or later biblical covenants need their own passages."],"claimIds":["creation-covenant-2-1","creation-covenant-2-2"]},{"id":"creation-covenant-section-3","title":"Providence and the mystery of suffering","paragraphs":["Providence is the theological term used here for God’s sustaining and governing care. Colossians speaks of all things being created through and for the Son, and held together in him. Westminster’s account supplies a specifically Reformed formulation. These are different kinds of evidence: a biblical text and an identified confession reflecting on it.","Romans 8 portrays creation as groaning while awaiting liberation. Trust in God’s purpose does not require pretending that decay, grief, or suffering are good in themselves. The chapter places hope alongside present pain. A pastor should avoid confidently assigning a hidden divine reason to someone else’s tragedy when the text gives no such explanation."],"claimIds":["creation-covenant-3-1","creation-covenant-3-2"]},{"id":"creation-covenant-section-4","title":"Receive, protect, and hope","paragraphs":["A practical response may include care for a local place, responsible use of resources, and attention to people whose lives are most exposed to environmental harm. These are applications of creaturely responsibility. They should be evaluated with sound information about a real situation rather than treated as ready-made policy conclusions from a single verse.","In prayer, gratitude and lament can belong together. Thank God for a concrete gift and name a concrete loss without forcing one to cancel the other. The visual sequence below connects creation, covenant, sustaining care, and hope as a study framework. It is a theological teaching diagram, not a claim that every biblical covenant has been covered by this one lesson."],"claimIds":["creation-covenant-4-1","creation-covenant-4-2"]},{"id":"creation-covenant-section-5","title":"Read a promise at its stated scope","paragraphs":["Write the covenant’s participants and promise in separate columns. Notice that the sign recalls a particular commitment rather than granting every reader a promise about every danger. This simple exercise helps prevent a broad feeling of reassurance from replacing what the passage says. The same practice can later be used with other covenants, where the parties and terms must be read afresh.","Then place Romans 8’s language of groaning beside its language of hope. Ask how a prayer can acknowledge both without explaining away either. A responsible testimony may express confidence and gratitude while admitting that some suffering remains unresolved. That admission is consistent with the chapter’s waiting, not evidence that the reader has failed to understand hope."],"claimIds":["creation-covenant-5-1","creation-covenant-5-2"]}],"languageNote":{"term":"Providence","transliteration":"English theological vocabulary","meaning":"God’s sustaining and governing care for creation.","caution":"This definition summarizes a doctrinal topic. It does not identify an original Hebrew word in Genesis 1 or disclose the purpose of an individual disaster.","sourceUrl":"https://www.opc.org/wcf.html"},"relatedPassages":[{"reference":"Genesis 9:8–17","url":"https://ebible.org/engwebp/GEN09.htm"},{"reference":"Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm"},{"reference":"Romans 8:18–25","url":"https://ebible.org/engwebp/ROM08.htm"}],"consensus":"The Nicene profile confesses God as creator. Creation’s goodness and dependence upon God are the lesson’s baseline; detailed models of origins remain outside that shared statement.","disputed":"Christians differ about the days of Genesis, evolutionary accounts, covenant systems, and models of providence. The confessional sources are identified rather than presented as a universal solution.","application":["Name one received gift and one responsibility arising from it.","Practice lament without claiming to explain God’s hidden purpose in a tragedy."],"reflection":["Where does gratitude challenge my sense of ownership?","Can I remain hopeful without denying another person’s pain?"],"discussion":["Which parties and promise does Genesis 9 actually name?","How would a group distinguish a biblical principle from a policy judgment?"],"quiz":[{"question":"Who is included in the Genesis 9 covenant?","options":["Only Noah personally","Noah, his descendants, and living creatures","Only future kings"],"answer":1,"explanation":"Genesis 9:8–17 explicitly expands the covenant beyond Noah alone."},{"question":"How does Romans 8 portray creation now?","options":["As groaning in hope","As having no future","As already free of every pain"],"answer":0,"explanation":"Romans 8:18–25 places creation’s groaning alongside hope of liberation."}],"sources":[{"id":"creation","title":"World English Bible (Updated): Genesis 1:1–31","url":"https://ebible.org/engwebp/GEN01.htm","locator":"Genesis 1:1–31","category":"A"},{"id":"noah","title":"World English Bible (Updated): Genesis 9:8–17","url":"https://ebible.org/engwebp/GEN09.htm","locator":"Genesis 9:8–17","category":"A"},{"id":"colossians","title":"World English Bible (Updated): Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm","locator":"Colossians 1:15–20","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 8:18–25","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:18–25","category":"A"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"}],"claims":[{"id":"creation-covenant-1-1","text":"Genesis 1 presents God as creator of the heavens and the earth. Its ordered sequence repeatedly names the goodness of what is made and culminates in a judgment that the whole is very good. The lesson begins with that theological witness. It does not turn a short introduction into a ruling on every scientific or literary question associated with the chapter.","sourceIds":["creation"],"locator":"Genesis 1:1–31; editorial theological application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-1-2","text":"To call the world created is to confess dependence rather than self-sufficiency. Gratitude and responsibility are reasonable applications: food, land, other creatures, and human neighbors are received within a world whose source is God. These are implications drawn for discipleship, not additional sentences that can be inserted into Genesis as verbatim text.","sourceIds":["creation"],"locator":"Genesis 1:1–31; editorial theological application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-2-1","text":"Genesis 9 identifies a covenant with Noah, his descendants, and living creatures. Its sign is the rainbow, and its particular promise concerns the destruction of all flesh by flood. Reading its named parties and stated promise prevents the covenant from becoming an undefined assurance that no painful event will happen again.","sourceIds":["noah"],"locator":"Genesis 9:8–17","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-2-2","text":"Covenant is not simply a synonym for a private bargain. In this narrative the promise is initiated by God and extends beyond Noah’s immediate household. A study group should inspect who speaks, who receives, what is promised, and what sign is named before connecting this covenant to others. Connections with Abraham or later biblical covenants need their own passages.","sourceIds":["noah"],"locator":"Genesis 9:8–17","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-3-1","text":"Providence is the theological term used here for God’s sustaining and governing care. Colossians speaks of all things being created through and for the Son, and held together in him. Westminster’s account supplies a specifically Reformed formulation. These are different kinds of evidence: a biblical text and an identified confession reflecting on it.","sourceIds":["colossians","romans","wcf"],"locator":"Colossians 1:15–20; Romans 8:18–25; Westminster Confession V","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-3-2","text":"Romans 8 portrays creation as groaning while awaiting liberation. Trust in God’s purpose does not require pretending that decay, grief, or suffering are good in themselves. The chapter places hope alongside present pain. A pastor should avoid confidently assigning a hidden divine reason to someone else’s tragedy when the text gives no such explanation.","sourceIds":["colossians","romans","wcf"],"locator":"Colossians 1:15–20; Romans 8:18–25; Westminster Confession V","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-4-1","text":"A practical response may include care for a local place, responsible use of resources, and attention to people whose lives are most exposed to environmental harm. These are applications of creaturely responsibility. They should be evaluated with sound information about a real situation rather than treated as ready-made policy conclusions from a single verse.","sourceIds":["creation","noah","romans"],"locator":"Genesis 1; 9:8–17; Romans 8:18–25; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-4-2","text":"In prayer, gratitude and lament can belong together. Thank God for a concrete gift and name a concrete loss without forcing one to cancel the other. The visual sequence below connects creation, covenant, sustaining care, and hope as a study framework. It is a theological teaching diagram, not a claim that every biblical covenant has been covered by this one lesson.","sourceIds":["creation","noah","romans"],"locator":"Genesis 1; 9:8–17; Romans 8:18–25; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-5-1","text":"Write the covenant’s participants and promise in separate columns. Notice that the sign recalls a particular commitment rather than granting every reader a promise about every danger. This simple exercise helps prevent a broad feeling of reassurance from replacing what the passage says. The same practice can later be used with other covenants, where the parties and terms must be read afresh.","sourceIds":["noah","romans"],"locator":"Genesis 9:8–17; Romans 8:18–25; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creation-covenant-5-2","text":"Then place Romans 8’s language of groaning beside its language of hope. Ask how a prayer can acknowledge both without explaining away either. A responsible testimony may express confidence and gratitude while admitting that some suffering remains unresolved. That admission is consistent with the chapter’s waiting, not evidence that the reader has failed to understand hope.","sourceIds":["noah","romans"],"locator":"Genesis 9:8–17; Romans 8:18–25; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"A framework for creaturely life","steps":["Creation received","Covenant remembered","Providence confessed","Hope practiced"]}},"creeds":{"id":"creeds","part":15,"title":"Creeds and the Memory of Christian Faith","subtitle":"Receiving a confession while reading history carefully","summary":"Early confessional patterns and later creeds help communities teach and remember their faith. Historical context and denominational reception must remain distinct from the biblical text.","readingMinutes":9,"scripture":{"reference":"1 Corinthians 15:3–4","text":"For I delivered to you first of all that which I also received: that Christ died for our sins according to the Scriptures, that he was buried, that he was raised on the third day according to the Scriptures,","context":"Read 1 Corinthians 15:1–11. Paul recalls received proclamation and witnesses before answering a dispute concerning resurrection.","url":"https://ebible.org/engwebp/1CO15.htm"},"objectives":["Distinguish a received biblical confession from a later creed.","Identify the councils associated with Nicene-Constantinopolitan confession.","Read a tradition’s self-description without claiming it is a neutral account of all Christians."],"essentialQuestions":["Why do communities summarize their faith?","What can a creed clarify, and what does it leave for further teaching?","How do historical reception and local approval differ?"],"sections":[{"id":"creeds-section-1","title":"Received and delivered","paragraphs":["In First Corinthians 15, Paul describes a message he received and delivered. The passage names Christ’s death, burial, resurrection, and appearances within an argument about resurrection. This is a useful biblical starting point for understanding why communities remember and teach a concise proclamation.","A later creed is not simply another verse of Scripture. It is an identified historical formulation that interprets and summarizes Christian belief. That distinction does not make it unimportant; it makes its role clear. A learner should know when a book is quoting the Bible, reporting a creed, or explaining how a tradition receives that creed."],"claimIds":["creeds-1-1","creeds-1-2"]},{"id":"creeds-section-2","title":"The Nicene setting","paragraphs":["The received Nicene-Constantinopolitan confession is associated with the councils of Nicaea in 325 and Constantinople in 381. The OCA presentation identifies these settings, and the Catholic Catechism likewise locates the creed in the first two ecumenical councils. These sources provide an accessible beginning; a full historical account would require critical study of the councils and their documents.","The creed addresses God, Christ, the Spirit, the church, baptism, resurrection, and the life to come. A summary selects and orders material for confession and teaching. It does not provide a complete encyclopedia of every Christian doctrine or a ready answer to every subsequent dispute."],"claimIds":["creeds-2-1","creeds-2-2"]},{"id":"creeds-section-3","title":"Reception differs across communities","paragraphs":["A source written by a church describes a received tradition from within that community. The OCA presentation explains Orthodox use; the Catholic Catechism explains Catholic teaching. Neither should be treated as though it were a detached survey of every Christian group. Naming the speaker and purpose is as necessary in historical research as it is in biblical interpretation.","Later confessions such as Westminster and the Baptist Faith and Message address their communities’ teaching in greater detail. They can be compared respectfully without being merged into a synthetic statement no church actually adopted. In this preview they function as evidence for particular positions, not as proof of local church approval."],"claimIds":["creeds-3-1","creeds-3-2"]},{"id":"creeds-section-4","title":"Use historical memory responsibly","paragraphs":["When studying a confession, record its name, date or historical setting, community, and the question it addresses. Separate the document’s wording from a teacher’s summary. If a translation or edition is used, identify it. These ordinary habits make later review possible and prevent memorable but inaccurate stories from becoming the group’s history.","A practical exercise is to compare a short biblical proclamation with a creed’s outline. Notice continuity of subject without pretending that the two documents have identical genre or authority. Then ask a local leader which creed or statement the church receives and what approval would be required before this textbook represents that community. The present preview remains educational material awaiting that review."],"claimIds":["creeds-4-1","creeds-4-2"]},{"id":"creeds-section-5","title":"Build a small historical source record","paragraphs":["For each document, record a title, a source link, and the section being discussed. Add a sentence identifying whether the document is Scripture, an ancient confession, or a later church explanation. This small record allows another reader to return to the evidence instead of relying on a memory of the lesson.","Historical humility also means avoiding imagined unanimity. A received confession may be central within the declared Nicene profile while its interpretation and authority differ across communities. A textbook can acknowledge that complexity without becoming unreadable: state the shared subject, identify the specific tradition when needed, and leave a clear note for further review. The resulting lesson supports conversation while preserving the difference between educational description and ecclesial judgment. Keep that distinction visible when sharing the resource with another congregation."],"claimIds":["creeds-5-1","creeds-5-2"]}],"languageNote":{"term":"Creed","transliteration":"Latin credo is identified in the cited church sources","meaning":"A concise confession or profession of faith.","caution":"The term names a historical genre. A creed’s reception and authority must be stated for the community using it; no local approval is implied.","sourceUrl":"https://www.vatican.va/archive/ENG0015/__P14.HTM"},"relatedPassages":[{"reference":"Matthew 28:19–20","url":"https://ebible.org/engwebp/MAT28.htm"},{"reference":"Luke 24:44–49","url":"https://ebible.org/engwebp/LUK24.htm"}],"consensus":"The textbook declares a broadly Nicene educational baseline. It does not claim all Christians receive every creed, later confession, or historical formulation in the same manner.","disputed":"The authority of councils and confessions, their precise reception, and later additions or interpretations differ. Local adoption requires a church’s own doctrinal approval.","application":["Identify your church’s received confession from an official source.","Label a historical quotation, paraphrase, and personal conclusion separately."],"reflection":["Which historical claim have I repeated without checking its source?","How can a received confession shape humility as well as clarity?"],"discussion":["What changes when we identify a source’s community and purpose?","Why should a local approval decision never be inferred from this preview’s Nicene profile?"],"quiz":[{"question":"Which councils are associated with the received Nicene-Constantinopolitan confession?","options":["Nicaea 325 and Constantinople 381","A modern publishing committee","No identifiable councils"],"answer":0,"explanation":"The cited church sources identify these conciliar settings; full historical study remains a larger task."},{"question":"Does this preview’s use of a creed establish church approval?","options":["Yes, automatically","No; local review is still required","Only if the typography is formal"],"answer":1,"explanation":"Historical reception and the approval of a particular educational resource are different matters."}],"sources":[{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 15:1–11","url":"https://ebible.org/engwebp/1CO15.htm","locator":"1 Corinthians 15:1–11","category":"A"},{"id":"nicene","title":"Nicene-Constantinopolitan Creed, Orthodox Church in America presentation","url":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed","locator":"The Symbol of Faith: Nicene Creed; councils of 325 and 381","category":"D"},{"id":"ccc-creeds","title":"Catechism of the Catholic Church: The Creeds","url":"https://www.vatican.va/archive/ENG0015/__P14.HTM","locator":"185–196","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"}],"claims":[{"id":"creeds-1-1","text":"In First Corinthians 15, Paul describes a message he received and delivered. The passage names Christ’s death, burial, resurrection, and appearances within an argument about resurrection. This is a useful biblical starting point for understanding why communities remember and teach a concise proclamation.","sourceIds":["corinthians","ccc-creeds"],"locator":"1 Corinthians 15:1–11; Catechism 185–196","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-1-2","text":"A later creed is not simply another verse of Scripture. It is an identified historical formulation that interprets and summarizes Christian belief. That distinction does not make it unimportant; it makes its role clear. A learner should know when a book is quoting the Bible, reporting a creed, or explaining how a tradition receives that creed.","sourceIds":["corinthians","ccc-creeds"],"locator":"1 Corinthians 15:1–11; Catechism 185–196","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-2-1","text":"The received Nicene-Constantinopolitan confession is associated with the councils of Nicaea in 325 and Constantinople in 381. The OCA presentation identifies these settings, and the Catholic Catechism likewise locates the creed in the first two ecumenical councils. These sources provide an accessible beginning; a full historical account would require critical study of the councils and their documents.","sourceIds":["nicene","ccc-creeds"],"locator":"OCA Nicene Creed introduction and text; Catechism 195","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-2-2","text":"The creed addresses God, Christ, the Spirit, the church, baptism, resurrection, and the life to come. A summary selects and orders material for confession and teaching. It does not provide a complete encyclopedia of every Christian doctrine or a ready answer to every subsequent dispute.","sourceIds":["nicene","ccc-creeds"],"locator":"OCA Nicene Creed introduction and text; Catechism 195","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-3-1","text":"A source written by a church describes a received tradition from within that community. The OCA presentation explains Orthodox use; the Catholic Catechism explains Catholic teaching. Neither should be treated as though it were a detached survey of every Christian group. Naming the speaker and purpose is as necessary in historical research as it is in biblical interpretation.","sourceIds":["nicene","ccc-creeds","wcf","bfm"],"locator":"OCA Nicene Creed reception; Catechism 185–196; Westminster Confession; Baptist Faith and Message","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-3-2","text":"Later confessions such as Westminster and the Baptist Faith and Message address their communities’ teaching in greater detail. They can be compared respectfully without being merged into a synthetic statement no church actually adopted. In this preview they function as evidence for particular positions, not as proof of local church approval.","sourceIds":["nicene","ccc-creeds","wcf","bfm"],"locator":"OCA Nicene Creed reception; Catechism 185–196; Westminster Confession; Baptist Faith and Message","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-4-1","text":"When studying a confession, record its name, date or historical setting, community, and the question it addresses. Separate the document’s wording from a teacher’s summary. If a translation or edition is used, identify it. These ordinary habits make later review possible and prevent memorable but inaccurate stories from becoming the group’s history.","sourceIds":["corinthians","nicene","ccc-creeds"],"locator":"1 Corinthians 15:1–11; Nicene confession; Catechism 185–196; editorial study method","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-4-2","text":"A practical exercise is to compare a short biblical proclamation with a creed’s outline. Notice continuity of subject without pretending that the two documents have identical genre or authority. Then ask a local leader which creed or statement the church receives and what approval would be required before this textbook represents that community. The present preview remains educational material awaiting that review.","sourceIds":["corinthians","nicene","ccc-creeds"],"locator":"1 Corinthians 15:1–11; Nicene confession; Catechism 185–196; editorial study method","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-5-1","text":"For each document, record a title, a source link, and the section being discussed. Add a sentence identifying whether the document is Scripture, an ancient confession, or a later church explanation. This small record allows another reader to return to the evidence instead of relying on a memory of the lesson.","sourceIds":["corinthians","nicene","ccc-creeds"],"locator":"1 Corinthians 15:1–11; OCA Nicene Creed; Catechism 185–196; original teaching exercise","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"creeds-5-2","text":"Historical humility also means avoiding imagined unanimity. A received confession may be central within the declared Nicene profile while its interpretation and authority differ across communities. A textbook can acknowledge that complexity without becoming unreadable: state the shared subject, identify the specific tradition when needed, and leave a clear note for further review. The resulting lesson supports conversation while preserving the difference between educational description and ecclesial judgment. Keep that distinction visible when sharing the resource with another congregation.","sourceIds":["corinthians","nicene","ccc-creeds"],"locator":"1 Corinthians 15:1–11; OCA Nicene Creed; Catechism 185–196; original teaching exercise","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"Reading a confession responsibly","steps":["Identify the document","Locate its setting","Read its confession","Record its reception"]}},"discipleship":{"id":"discipleship","part":14,"title":"Love of God and Love of Neighbor","subtitle":"Doctrine becoming a practiced way of life","summary":"Jesus’ answer about the greatest commandment joins devotion to God with love of neighbor. Christian ethics requires concrete discernment rather than a vague appeal to sincerity.","readingMinutes":8,"scripture":{"reference":"Matthew 22:39–40","text":"A second likewise is this, ‘You shall love your neighbor as yourself.’ The whole law and the prophets depend on these two commandments.”","context":"Read Matthew 22:34–40. In a sequence of questions, a legal expert asks Jesus about the greatest commandment. Jesus joins love of God to love of neighbor.","url":"https://ebible.org/engwebp/MAT22.htm"},"objectives":["State the two commandments Jesus places together.","Connect love with concrete action in a companion passage.","Distinguish an ethical principle from a specific policy decision."],"essentialQuestions":["How do devotion and responsibility to a neighbor belong together?","Why is sincerity alone insufficient to evaluate an action?","What does a concrete response require?"],"sections":[{"id":"discipleship-section-1","title":"Two commandments held together","paragraphs":["Matthew presents the question about the greatest commandment within a sequence of debates. Jesus answers with love of God and then names love of neighbor as a second commandment like it. His conclusion gives both a framing role for law and prophets. The lesson should preserve that relation rather than selecting one love as permission to ignore the other.","The passage is a concise orientation, not a complete manual for every ethical dilemma. “Love” needs attention to the neighbor’s real situation. An action can feel generous to the actor while being careless about its effect on someone else. Responsible application therefore requires listening, truthful information, and willingness to revise a mistaken approach."],"claimIds":["discipleship-1-1","discipleship-1-2"]},{"id":"discipleship-section-2","title":"Love expressed in deed and truth","paragraphs":["First John 3:16–18 relates love to Christ’s self-giving and then asks about a person who has resources but closes compassion to a brother in need. The instruction to love in deed and truth makes the ethical direction concrete. Words matter, but they cannot be used as a substitute for help when help is possible.","James 2 similarly uses the example of a person lacking clothing and daily food. A blessing without meeting bodily need becomes the test case for a claim about faith. Read these passages in their own arguments before combining them. Together they challenge a religious vocabulary that leaves a neighbor’s situation untouched."],"claimIds":["discipleship-2-1","discipleship-2-2"]},{"id":"discipleship-section-3","title":"Formation rather than performance","paragraphs":["Discipleship includes learning practices through which understanding and conduct are connected. Prayer, study, shared worship, truthfulness, and service can form habits, but the mere visibility of a habit is not proof of maturity. The selected passages direct attention to love’s relation to concrete people, not a public score of religious activity.","A community should also ask how power is used. Help can become a means of control if recipients are required to surrender dignity or silence disagreement. This is a pastoral application of attention to the neighbor, not an additional quotation from Matthew. Accountability is especially important when the person offering help also holds authority."],"claimIds":["discipleship-3-1","discipleship-3-2"]},{"id":"discipleship-section-4","title":"From principle to an accountable decision","paragraphs":["Choose one person or situation and ask four questions: what is needed, what is known, what action is possible, and how will the effect be reviewed? These questions make application inspectable. A policy about resources, safeguarding, justice, or public action will need further evidence beyond the general command to love.","For a group exercise, plan a small act of care with the recipient’s input where appropriate. Review whether it helped rather than celebrating only the intention. The diagram below is an original practice cycle, not a biblical formula. It keeps reflection connected to action and keeps action open to correction."],"claimIds":["discipleship-4-1","discipleship-4-2"]},{"id":"discipleship-section-5","title":"Review the effect, not only the intention","paragraphs":["An act of care should remain open to correction. After a group completes a project, ask whether the recipient’s actual need was met and whether the manner of helping respected them. If the answer is uncertain, learn more before repeating the activity. This is an application of attention to the neighbor rather than a demand that every good action produce an immediately measurable outcome.","A leader can model this practice by acknowledging an error without treating correction as disloyalty. The community learns that truth matters alongside compassion. When circumstances involve harm or unequal authority, listening should include the people most affected. Love of neighbor is too concrete to be satisfied by a slogan that keeps those neighbors from speaking about what happened. Make room for correction and a more faithful response."],"claimIds":["discipleship-5-1","discipleship-5-2"]}],"languageNote":{"term":"Discipleship","transliteration":"English study vocabulary","meaning":"Learning and practicing a life shaped by following Jesus.","caution":"No claim is made that a single Greek word determines every modern ministry method. The passage’s actual commands remain the starting point.","sourceUrl":"https://ebible.org/engwebp/MAT22.htm"},"relatedPassages":[{"reference":"1 John 3:16–18","url":"https://ebible.org/engwebp/1JN03.htm"},{"reference":"James 2:14–17","url":"https://ebible.org/engwebp/JAS02.htm"},{"reference":"Matthew 28:19–20","url":"https://ebible.org/engwebp/MAT28.htm"}],"consensus":"The selected profile receives love of God and neighbor as central to Christian discipleship. The cited texts connect love and faith with action toward people in need.","disputed":"Christians differ on many public, social, and personal ethical judgments. A general command must not be presented as though it automatically verifies every proposed policy.","application":["Ask a recipient what assistance is useful before deciding for them.","Choose one act of care and review its effect honestly."],"reflection":["Where do good intentions conceal a failure to listen?","What practice helps connect my study with a neighbor’s need?"],"discussion":["How do Matthew, First John, and James approach the relation of love and action?","What extra evidence would a specific policy require?"],"quiz":[{"question":"What does Jesus place beside love of God?","options":["Love of neighbor","Religious visibility","A guarantee of approval"],"answer":0,"explanation":"Matthew 22:39 names love of neighbor as the second commandment like the first."},{"question":"What does 1 John 3:18 emphasize?","options":["Words without action","Love in deed and truth","An end to discernment"],"answer":1,"explanation":"The passage links love to practical compassion rather than words alone."}],"sources":[{"id":"matthew","title":"World English Bible (Updated): Matthew 22:34–40","url":"https://ebible.org/engwebp/MAT22.htm","locator":"Matthew 22:34–40","category":"A"},{"id":"john","title":"World English Bible (Updated): 1 John 3:16–18","url":"https://ebible.org/engwebp/1JN03.htm","locator":"1 John 3:16–18","category":"A"},{"id":"james","title":"World English Bible (Updated): James 2:14–17","url":"https://ebible.org/engwebp/JAS02.htm","locator":"James 2:14–17","category":"A"}],"claims":[{"id":"discipleship-1-1","text":"Matthew presents the question about the greatest commandment within a sequence of debates. Jesus answers with love of God and then names love of neighbor as a second commandment like it. His conclusion gives both a framing role for law and prophets. The lesson should preserve that relation rather than selecting one love as permission to ignore the other.","sourceIds":["matthew"],"locator":"Matthew 22:34–40; ethical application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-1-2","text":"The passage is a concise orientation, not a complete manual for every ethical dilemma. “Love” needs attention to the neighbor’s real situation. An action can feel generous to the actor while being careless about its effect on someone else. Responsible application therefore requires listening, truthful information, and willingness to revise a mistaken approach.","sourceIds":["matthew"],"locator":"Matthew 22:34–40; ethical application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-2-1","text":"First John 3:16–18 relates love to Christ’s self-giving and then asks about a person who has resources but closes compassion to a brother in need. The instruction to love in deed and truth makes the ethical direction concrete. Words matter, but they cannot be used as a substitute for help when help is possible.","sourceIds":["john","james"],"locator":"1 John 3:16–18; James 2:14–17","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-2-2","text":"James 2 similarly uses the example of a person lacking clothing and daily food. A blessing without meeting bodily need becomes the test case for a claim about faith. Read these passages in their own arguments before combining them. Together they challenge a religious vocabulary that leaves a neighbor’s situation untouched.","sourceIds":["john","james"],"locator":"1 John 3:16–18; James 2:14–17","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-3-1","text":"Discipleship includes learning practices through which understanding and conduct are connected. Prayer, study, shared worship, truthfulness, and service can form habits, but the mere visibility of a habit is not proof of maturity. The selected passages direct attention to love’s relation to concrete people, not a public score of religious activity.","sourceIds":["matthew","john"],"locator":"Matthew 22:37–40; 1 John 3:16–18; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-3-2","text":"A community should also ask how power is used. Help can become a means of control if recipients are required to surrender dignity or silence disagreement. This is a pastoral application of attention to the neighbor, not an additional quotation from Matthew. Accountability is especially important when the person offering help also holds authority.","sourceIds":["matthew","john"],"locator":"Matthew 22:37–40; 1 John 3:16–18; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-4-1","text":"Choose one person or situation and ask four questions: what is needed, what is known, what action is possible, and how will the effect be reviewed? These questions make application inspectable. A policy about resources, safeguarding, justice, or public action will need further evidence beyond the general command to love.","sourceIds":["matthew","john","james"],"locator":"Matthew 22:37–40; 1 John 3:18; James 2:15–17; teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-4-2","text":"For a group exercise, plan a small act of care with the recipient’s input where appropriate. Review whether it helped rather than celebrating only the intention. The diagram below is an original practice cycle, not a biblical formula. It keeps reflection connected to action and keeps action open to correction.","sourceIds":["matthew","john","james"],"locator":"Matthew 22:37–40; 1 John 3:18; James 2:15–17; teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-5-1","text":"An act of care should remain open to correction. After a group completes a project, ask whether the recipient’s actual need was met and whether the manner of helping respected them. If the answer is uncertain, learn more before repeating the activity. This is an application of attention to the neighbor rather than a demand that every good action produce an immediately measurable outcome.","sourceIds":["matthew","john","james"],"locator":"Matthew 22:37–40; 1 John 3:17–18; James 2:15–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"discipleship-5-2","text":"A leader can model this practice by acknowledging an error without treating correction as disloyalty. The community learns that truth matters alongside compassion. When circumstances involve harm or unequal authority, listening should include the people most affected. Love of neighbor is too concrete to be satisfied by a slogan that keeps those neighbors from speaking about what happened. Make room for correction and a more faithful response.","sourceIds":["matthew","john","james"],"locator":"Matthew 22:37–40; 1 John 3:17–18; James 2:15–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"cycle","title":"An accountable practice of care","steps":["Listen to the need","Discern with evidence","Act with care","Review and learn"]}},"holy-spirit":{"id":"holy-spirit","part":9,"title":"The Holy Spirit and the Common Good","subtitle":"Many gifts, one body, a life of love","summary":"Paul addresses spiritual gifts within a community that needs unity, mutual dependence, and care. The lesson distinguishes the biblical list from disputed accounts of gifts today.","readingMinutes":9,"scripture":{"reference":"1 Corinthians 12:4–7","text":"Now there are various kinds of gifts, but the same Spirit. There are various kinds of service, and the same Lord. There are various kinds of workings, but the same God who works all things in all. But to each one is given the manifestation of the Spirit for the profit of all.","context":"Read 1 Corinthians 12–14. Gifts are discussed alongside the body’s mutual dependence, the indispensable way of love, and the ordering of the gathering.","url":"https://ebible.org/engwebp/1CO12.htm"},"objectives":["Identify the common good as a stated purpose of gifts.","Explain the body metaphor’s challenge to status and exclusion.","Distinguish textual descriptions from claims about contemporary practice."],"essentialQuestions":["Whom is a gift intended to serve?","What happens when a community ranks people by visible ability?","How should disputed spiritual claims be evaluated?"],"sections":[{"id":"holy-spirit-section-1","title":"The Spirit and the confession of Jesus","paragraphs":["Paul begins his discussion by connecting speech about Jesus with the Holy Spirit. The topic is not a detached catalogue of unusual experiences. It is life in a community learning to recognize and serve its Lord. The repeated language of the same Spirit, Lord, and God counters the idea that variety must produce rivalry.","Pneumatology is the conventional theological label for the study of the Holy Spirit. In the Nicene profile, the Spirit belongs within the confession of the one God. The lesson’s focus on service should not reduce the Spirit to an impersonal force or a human talent. Its biblical starting point is the Spirit’s action within a worshiping community."],"claimIds":["holy-spirit-1-1","holy-spirit-1-2"]},{"id":"holy-spirit-section-2","title":"Gifts directed toward others","paragraphs":["Verse 7 gives a criterion that beginners can readily inspect: the manifestation is for the profit of all. Paul names a variety of gifts and says the same Spirit distributes them as he desires. The passage resists both envy of another person’s role and pride in one’s own. It does not present a gift as an individual’s spiritual status badge.","A practical question follows: who benefits from the way this ability is exercised? The answer should include people beyond the most visible leader. The criterion is not a complete policy for every church gathering, but it directs attention away from self-display and toward the needs of the community."],"claimIds":["holy-spirit-2-1","holy-spirit-2-2"]},{"id":"holy-spirit-section-3","title":"The body needs its members","paragraphs":["Paul compares the community to a body with many members. A foot cannot remove itself by wishing to be a hand, and an eye cannot dismiss a hand as unnecessary. The metaphor emphasizes belonging and interdependence. A community that treats less visible members as disposable contradicts the movement of the argument.","Romans 8 speaks of the Spirit’s help in weakness and intercession when believers do not know how to pray. This is a useful companion to discussion of gifts: the Spirit’s presence is not measured only by impressive ability. Weakness is named within the life of those who belong to God, not excluded as proof of failure."],"claimIds":["holy-spirit-3-1","holy-spirit-3-2"]},{"id":"holy-spirit-section-4","title":"Discernment without invented certainty","paragraphs":["The continuation, cessation, and regulation of particular gifts are disputed among Christian communities. This lesson verifies what Paul’s passage says and leaves the contemporary doctrinal configuration for local review. It does not certify a present claim to prophecy, healing, or special knowledge simply because biblical language is used.","For group study, identify an overlooked form of service and ask how it supports another person’s participation. Read the body paragraph before creating a ministry roster. The visual below is a teaching aid about shared service, not a diagnostic tool that can assign a person’s gift without conversation, practice, and accountable discernment."],"claimIds":["holy-spirit-4-1","holy-spirit-4-2"]},{"id":"holy-spirit-section-5","title":"A common-good question for every ministry","paragraphs":["When a group evaluates a proposed ministry, ask who can participate, who receives care, and who might be overlooked. The body metaphor gives reason to consider members whose needs are not easily expressed. An exciting activity can still require revision if it consistently excludes someone or elevates one person at others’ expense. These are practical judgments, made in light of the chapter’s direction toward shared benefit.","Allow the same person to be both a contributor and someone needing help. Romans 8’s language of weakness resists the pressure to appear permanently strong. A community can pray, listen, and provide ordinary support while remaining cautious about spectacular claims. Such care does not require every member to resolve the controversy over the continuation of particular gifts before acting lovingly."],"claimIds":["holy-spirit-5-1","holy-spirit-5-2"]}],"languageNote":{"term":"Pneumatology","transliteration":"Conventional theological label","meaning":"The doctrinal study of the Holy Spirit.","caution":"The label is not proof that every occurrence of “spirit” means the same thing. Context is needed; no isolated Greek root is used to authenticate a contemporary claim.","sourceUrl":"https://ebible.org/engwebp/1CO12.htm"},"relatedPassages":[{"reference":"Romans 8:14–27","url":"https://ebible.org/engwebp/ROM08.htm"},{"reference":"Acts 2:1–21","url":"https://ebible.org/engwebp/ACT02.htm"}],"consensus":"The Nicene profile confesses the Holy Spirit. The textual purpose of gifts in 1 Corinthians 12:7 is the profit of all.","disputed":"Continuation or cessation of particular gifts, the relation of Spirit baptism to initiation, and criteria for contemporary prophecy require separate church review. This preview makes no certification of an individual claim.","application":["Thank someone whose service usually goes unnoticed.","Evaluate a ministry practice by how it serves the common good."],"reflection":["Do I confuse visibility with spiritual value?","How can I receive another person’s service without comparison?"],"discussion":["What does the body metaphor challenge in a church’s habits?","How does Romans 8 complicate the idea that spiritual life always feels powerful?"],"quiz":[{"question":"What is the stated purpose in 1 Corinthians 12:7?","options":["The profit of all","Proof of superior status","Freedom from needing others"],"answer":0,"explanation":"The passage directs gifts toward the common good."},{"question":"What does the body metaphor emphasize?","options":["Only the most visible member matters","Mutual belonging and dependence","Uniform abilities for all members"],"answer":1,"explanation":"Many different members belong to one body and cannot dismiss one another."}],"sources":[{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 12:1–26","url":"https://ebible.org/engwebp/1CO12.htm","locator":"1 Corinthians 12:1–26","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 8:14–27","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:14–27","category":"A"},{"id":"nicene","title":"Nicene-Constantinopolitan Creed, Orthodox Church in America presentation","url":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed","locator":"The Symbol of Faith: Nicene Creed; councils of 325 and 381","category":"D"}],"claims":[{"id":"holy-spirit-1-1","text":"Paul begins his discussion by connecting speech about Jesus with the Holy Spirit. The topic is not a detached catalogue of unusual experiences. It is life in a community learning to recognize and serve its Lord. The repeated language of the same Spirit, Lord, and God counters the idea that variety must produce rivalry.","sourceIds":["corinthians","nicene"],"locator":"1 Corinthians 12:1–7; Nicene confession","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-1-2","text":"Pneumatology is the conventional theological label for the study of the Holy Spirit. In the Nicene profile, the Spirit belongs within the confession of the one God. The lesson’s focus on service should not reduce the Spirit to an impersonal force or a human talent. Its biblical starting point is the Spirit’s action within a worshiping community.","sourceIds":["corinthians","nicene"],"locator":"1 Corinthians 12:1–7; Nicene confession","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-2-1","text":"Verse 7 gives a criterion that beginners can readily inspect: the manifestation is for the profit of all. Paul names a variety of gifts and says the same Spirit distributes them as he desires. The passage resists both envy of another person’s role and pride in one’s own. It does not present a gift as an individual’s spiritual status badge.","sourceIds":["corinthians"],"locator":"1 Corinthians 12:7–11; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-2-2","text":"A practical question follows: who benefits from the way this ability is exercised? The answer should include people beyond the most visible leader. The criterion is not a complete policy for every church gathering, but it directs attention away from self-display and toward the needs of the community.","sourceIds":["corinthians"],"locator":"1 Corinthians 12:7–11; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-3-1","text":"Paul compares the community to a body with many members. A foot cannot remove itself by wishing to be a hand, and an eye cannot dismiss a hand as unnecessary. The metaphor emphasizes belonging and interdependence. A community that treats less visible members as disposable contradicts the movement of the argument.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:12–26; Romans 8:26–27","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-3-2","text":"Romans 8 speaks of the Spirit’s help in weakness and intercession when believers do not know how to pray. This is a useful companion to discussion of gifts: the Spirit’s presence is not measured only by impressive ability. Weakness is named within the life of those who belong to God, not excluded as proof of failure.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:12–26; Romans 8:26–27","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-4-1","text":"The continuation, cessation, and regulation of particular gifts are disputed among Christian communities. This lesson verifies what Paul’s passage says and leaves the contemporary doctrinal configuration for local review. It does not certify a present claim to prophecy, healing, or special knowledge simply because biblical language is used.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:7–26; Romans 8:26–27; editorial limits and application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-4-2","text":"For group study, identify an overlooked form of service and ask how it supports another person’s participation. Read the body paragraph before creating a ministry roster. The visual below is a teaching aid about shared service, not a diagnostic tool that can assign a person’s gift without conversation, practice, and accountable discernment.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:7–26; Romans 8:26–27; editorial limits and application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-5-1","text":"When a group evaluates a proposed ministry, ask who can participate, who receives care, and who might be overlooked. The body metaphor gives reason to consider members whose needs are not easily expressed. An exciting activity can still require revision if it consistently excludes someone or elevates one person at others’ expense. These are practical judgments, made in light of the chapter’s direction toward shared benefit.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:7, 22–26; Romans 8:26–27; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"holy-spirit-5-2","text":"Allow the same person to be both a contributor and someone needing help. Romans 8’s language of weakness resists the pressure to appear permanently strong. A community can pray, listen, and provide ordinary support while remaining cautious about spectacular claims. Such care does not require every member to resolve the controversy over the continuation of particular gifts before acting lovingly.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 12:7, 22–26; Romans 8:26–27; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"cycle","title":"Gifts in community","steps":["Received from the Spirit","Practiced in love","Serving the common good","Strengthening one body"]}},"image-of-god":{"id":"image-of-god","part":6,"title":"Humanity in the Image of God","subtitle":"Dignity received, responsibility shared","summary":"Genesis locates human dignity in relation to God, not in achievement, social standing, or independence. The image language also gives humanity a responsibility within creation.","readingMinutes":8,"scripture":{"reference":"Genesis 1:27","text":"God created man in his own image. In God’s image he created him; male and female he created them.","context":"Read Genesis 1:26–31. Humanity is created in the image of God within the account of the good creation and receives a vocation concerning the earth and its creatures.","url":"https://ebible.org/engwebp/GEN01.htm"},"objectives":["Locate image language in its narrative setting.","Connect dignity and responsibility without ranking people by capacity.","Distinguish the biblical statement from competing accounts of what the image entails."],"essentialQuestions":["What grounds human dignity in this passage?","How should responsibility affect the treatment of neighbors?","What should be said cautiously about the image?"],"sections":[{"id":"image-of-god-section-1","title":"The image as a received dignity","paragraphs":["Genesis 1 places human life within God’s good creation and describes humanity in relation to God’s image. Male and female are included in the wording. The dignity named here is received with human existence; it is not presented as a reward for wealth, intelligence, strength, or public usefulness. The lesson draws that ethical implication explicitly rather than pretending the chapter lists every modern situation.","This account challenges a community to examine whom it notices and whom it overlooks. An infant, an older neighbor, a person with a disability, and a person who cannot return a favor are not outside humanity’s dignity. These examples are contemporary applications of the passage’s scope, not a claim that Genesis employs modern legal or medical categories."],"claimIds":["image-of-god-1-1","image-of-god-1-2"]},{"id":"image-of-god-section-2","title":"Image and vocation belong together","paragraphs":["The image statement appears alongside commands concerning fruitfulness and rule within creation. Human responsibility is therefore part of the setting, not an unrelated topic added after dignity. The text gives humanity a place within the world God calls good; it should not be used casually to justify waste or indifference to other life.","“Image” has received several theological explanations, including attention to relationship, capacity, representation, and vocation. This introductory lesson does not declare one explanatory model to be the whole meaning. It begins with what the text actually links: God’s creative action, humanity, male and female, blessing, and responsibility. Further comparisons need identified scholarly or confessional sources."],"claimIds":["image-of-god-2-1","image-of-god-2-2"]},{"id":"image-of-god-section-3","title":"Dignity after the fracture of human life","paragraphs":["Genesis 9:5–6 uses the image of God as a reason for the seriousness of taking human life. In the narrative sequence this comes after the flood, so image language is not confined to the opening creation scene. The passage is ethically weighty, and a beginner’s lesson should not reduce it to a casual slogan or use it to settle every disputed question of punishment.","Christian language about sin and redemption must not become a reason to deny a neighbor’s humanity. The selected reading supports the gravity of violence; it does not identify a social group as less deserving of care. A local church can apply this principle to its practices while documenting the further moral reasoning required for particular decisions."],"claimIds":["image-of-god-3-1","image-of-god-3-2"]},{"id":"image-of-god-section-4","title":"Practice dignity in ordinary encounters","paragraphs":["Choose one ordinary setting: a meeting, a meal, a hospital visit, or an online exchange. Ask whose needs are treated as an inconvenience and whose voice receives automatic attention. A practical response can be modest and concrete—providing accessible material, listening without interruption, or offering assistance without stripping a person of agency.","The lesson’s comparison diagram keeps dignity and vocation together. It does not classify some people as bearing more of God’s image than others. In a discussion, resist using “image of God” as an impressive phrase that leaves actual behavior untouched. Ask what should change in the way a named neighbor is welcomed and protected."],"claimIds":["image-of-god-4-1","image-of-god-4-2"]},{"id":"image-of-god-section-5","title":"A dignity audit for a study group","paragraphs":["Before discussing an abstract definition, consider the group’s own practices. Are materials readable for someone with poor vision? Can a quiet participant contribute without being rushed? Is practical help offered respectfully? These questions are not a substitute for studying the passage. They test whether an ethical inference about dignity reaches ordinary conduct.","Keep the distinction between the textual principle and the practical decision visible. A specific accessibility measure may require asking a participant what works, while a safeguarding policy requires further professional and legal information. Scripture’s image language provides a serious moral orientation; responsible action also takes the person and the circumstances seriously."],"claimIds":["image-of-god-5-1","image-of-god-5-2"]}],"languageNote":{"term":"Image of God","transliteration":"WEB wording in Genesis 1:27","meaning":"The phrase identifies a relation God gives humanity in creation.","caution":"The English phrase does not by itself settle all debates about capacities, embodiment, or representation. No unverified Hebrew etymology is offered.","sourceUrl":"https://ebible.org/engwebp/GEN01.htm"},"relatedPassages":[{"reference":"Genesis 9:5–7","url":"https://ebible.org/engwebp/GEN09.htm"},{"reference":"Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm"}],"consensus":"The profile affirms the dignity of human persons as creatures of God. Genesis explicitly applies image language to humanity, including male and female.","disputed":"The precise definition of the image, its relation to sin, and detailed ethical applications need further confessional and scholarly review. This lesson does not rank human dignity by measured capacity.","application":["Review one church activity for accessibility and welcome.","Speak about someone who needs care without reducing them to a problem."],"reflection":["Whose dignity do I find easiest to overlook?","How can responsibility and dependence coexist?"],"discussion":["What does the passage state, and what moral inferences are we drawing?","How can assistance preserve another person’s participation and agency?"],"quiz":[{"question":"What grounds image language in Genesis 1?","options":["Human achievement","God’s creative action","Membership in a powerful group"],"answer":1,"explanation":"God creates humanity in the divine image; it is not introduced as an earned status."},{"question":"What does Genesis 9 connect with the image?","options":["The seriousness of human life and violence","A hierarchy of intelligence","The disappearance of responsibility"],"answer":0,"explanation":"Genesis 9:5–6 grounds the gravity of taking human life in God’s making humanity in his image."}],"sources":[{"id":"genesis","title":"World English Bible (Updated): Genesis 1:26–31","url":"https://ebible.org/engwebp/GEN01.htm","locator":"Genesis 1:26–31","category":"A"},{"id":"noah","title":"World English Bible (Updated): Genesis 9:5–7","url":"https://ebible.org/engwebp/GEN09.htm","locator":"Genesis 9:5–7","category":"A"}],"claims":[{"id":"image-of-god-1-1","text":"Genesis 1 places human life within God’s good creation and describes humanity in relation to God’s image. Male and female are included in the wording. The dignity named here is received with human existence; it is not presented as a reward for wealth, intelligence, strength, or public usefulness. The lesson draws that ethical implication explicitly rather than pretending the chapter lists every modern situation.","sourceIds":["genesis"],"locator":"Genesis 1:26–31; pastoral implications","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-1-2","text":"This account challenges a community to examine whom it notices and whom it overlooks. An infant, an older neighbor, a person with a disability, and a person who cannot return a favor are not outside humanity’s dignity. These examples are contemporary applications of the passage’s scope, not a claim that Genesis employs modern legal or medical categories.","sourceIds":["genesis"],"locator":"Genesis 1:26–31; pastoral implications","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-2-1","text":"The image statement appears alongside commands concerning fruitfulness and rule within creation. Human responsibility is therefore part of the setting, not an unrelated topic added after dignity. The text gives humanity a place within the world God calls good; it should not be used casually to justify waste or indifference to other life.","sourceIds":["genesis"],"locator":"Genesis 1:26–31; limits on interpretive models","category":"A","verification":"references-checked","uncertainty":"The precise scope of image language is debated; only textual relationships are asserted here."},{"id":"image-of-god-2-2","text":"“Image” has received several theological explanations, including attention to relationship, capacity, representation, and vocation. This introductory lesson does not declare one explanatory model to be the whole meaning. It begins with what the text actually links: God’s creative action, humanity, male and female, blessing, and responsibility. Further comparisons need identified scholarly or confessional sources.","sourceIds":["genesis"],"locator":"Genesis 1:26–31; limits on interpretive models","category":"A","verification":"references-checked","uncertainty":"The precise scope of image language is debated; only textual relationships are asserted here."},{"id":"image-of-god-3-1","text":"Genesis 9:5–6 uses the image of God as a reason for the seriousness of taking human life. In the narrative sequence this comes after the flood, so image language is not confined to the opening creation scene. The passage is ethically weighty, and a beginner’s lesson should not reduce it to a casual slogan or use it to settle every disputed question of punishment.","sourceIds":["noah"],"locator":"Genesis 9:5–7; ethical application distinguished from policy decisions","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-3-2","text":"Christian language about sin and redemption must not become a reason to deny a neighbor’s humanity. The selected reading supports the gravity of violence; it does not identify a social group as less deserving of care. A local church can apply this principle to its practices while documenting the further moral reasoning required for particular decisions.","sourceIds":["noah"],"locator":"Genesis 9:5–7; ethical application distinguished from policy decisions","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-4-1","text":"Choose one ordinary setting: a meeting, a meal, a hospital visit, or an online exchange. Ask whose needs are treated as an inconvenience and whose voice receives automatic attention. A practical response can be modest and concrete—providing accessible material, listening without interruption, or offering assistance without stripping a person of agency.","sourceIds":["genesis","noah"],"locator":"Genesis 1:26–31; 9:5–7; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-4-2","text":"The lesson’s comparison diagram keeps dignity and vocation together. It does not classify some people as bearing more of God’s image than others. In a discussion, resist using “image of God” as an impressive phrase that leaves actual behavior untouched. Ask what should change in the way a named neighbor is welcomed and protected.","sourceIds":["genesis","noah"],"locator":"Genesis 1:26–31; 9:5–7; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-5-1","text":"Before discussing an abstract definition, consider the group’s own practices. Are materials readable for someone with poor vision? Can a quiet participant contribute without being rushed? Is practical help offered respectfully? These questions are not a substitute for studying the passage. They test whether an ethical inference about dignity reaches ordinary conduct.","sourceIds":["genesis","noah"],"locator":"Genesis 1:26–31; 9:5–7; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"image-of-god-5-2","text":"Keep the distinction between the textual principle and the practical decision visible. A specific accessibility measure may require asking a participant what works, while a safeguarding policy requires further professional and legal information. Scripture’s image language provides a serious moral orientation; responsible action also takes the person and the circumstances seriously.","sourceIds":["genesis","noah"],"locator":"Genesis 1:26–31; 9:5–7; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"comparison","title":"Dignity and vocation","steps":["Created by God","Dignity received","Neighbors protected","Responsibility practiced"]}},"interpreting-scripture":{"id":"interpreting-scripture","part":1,"title":"Learning to Read Scripture Well","subtitle":"Observation, context, interpretation, and faithful response","summary":"A practical introduction to theology that reads passages in their literary setting, distinguishes observation from inference, and brings questions to a learning community.","readingMinutes":9,"scripture":{"reference":"Luke 24:27","text":"Beginning from Moses and from all the prophets, he explained to them in all the Scriptures the things concerning himself.","context":"Read Luke 24:13–35. Two disappointed disciples walk toward Emmaus after Jesus’ death. The risen Jesus interprets Scripture before they recognize him in the breaking of bread.","url":"https://ebible.org/engwebp/LUK24.htm"},"objectives":["Distinguish a biblical quotation from an interpretation.","Identify genre, speaker, audience, and immediate context.","Explain why a Christian reading considers both the passage and the wider biblical story."],"essentialQuestions":["What does the passage actually say?","How does context discipline an attractive interpretation?","How can a group disagree without misrepresenting Scripture?"],"sections":[{"id":"interpreting-scripture-section-1","title":"Theology begins with attentive listening","paragraphs":["Theology is disciplined reflection on God and the life of faith. In Luke’s Emmaus narrative, explanation, hospitality, recognition, and witness belong together. The disciples possess reports about Jesus but struggle to understand their meaning. The story invites a patient reading in which the biblical narrative corrects an incomplete expectation. It does not authorize a teacher to find any desired meaning behind every word.","Begin with observation. Name the speaker and audience; notice repeated phrases, contrasts, questions, and actions. Then ask what kind of writing you are reading. A lament, a parable, a letter, and a narrative do different kinds of work. Write down what can be pointed to in the passage before offering an explanation. This practice gives other readers something they can inspect rather than asking them to trust your confidence."],"claimIds":["interpreting-scripture-1-1","interpreting-scripture-1-2"]},{"id":"interpreting-scripture-section-2","title":"Read paragraphs before collecting verses","paragraphs":["A verse belongs to a paragraph and a book before it becomes an item in a topical collection. The Emmaus travelers interpret the crucifixion through their disappointed hope for Israel’s redemption. Jesus answers within the story of Moses and the prophets. A Christian interpretation therefore asks how a passage relates to the whole biblical witness, while still respecting its original setting.","Move through four questions: what is present, how it functions, what conclusion the evidence supports, and what faithful response might follow. A contemporary application is a further step, not a replacement for interpretation. For example, the travelers’ hospitality can prompt reflection on welcoming strangers without becoming a promise that every guest is an unrecognized divine messenger."],"claimIds":["interpreting-scripture-2-1","interpreting-scripture-2-2"]},{"id":"interpreting-scripture-section-3","title":"Read with the church and with honest limits","paragraphs":["This textbook identifies the World English Bible when it quotes Scripture. The lesson author’s explanation remains interpretation. Historical creeds and denominational statements help readers see how communities have understood the text; they must be identified as such. The Catholic Catechism describes creeds as summaries of Christian faith associated with baptism. That is evidence about a tradition’s self-understanding, not permission to label every later opinion universal.","When evidence is incomplete, state the question. A useful group response is, “The passage says this; our explanation is this; another tradition understands it differently.” Keep notes about sources and uncertainty. End study with a response proportionate to what has been established: prayer, repentance, gratitude, further investigation, or a concrete act of love. An unresolved question can be an honest result of careful reading."],"claimIds":["interpreting-scripture-3-1","interpreting-scripture-3-2"]},{"id":"interpreting-scripture-section-4","title":"An exercise in accountable reading","paragraphs":["Try the method with the travelers’ conversation. First record their stated hope and their account of the reports they heard. Next record Jesus’ response and the story’s movement toward recognition. Only then propose what the episode teaches about disappointment and understanding. This order lets another reader inspect the reasoning. If a proposed conclusion depends on something the narrative never says, identify that missing step.","A group can also compare the questions its members bring to the passage. One reader may notice sadness, another hospitality, another the role of Scripture. These observations can enrich one another without making every interpretation equally supported. Ask each reader to point to the language that prompted the observation. A leader can summarize the evidence, name a genuine disagreement, and choose a question for further study. The aim is shared attention and an honest response, not a contest to produce the most surprising meaning. Revisit the passage after discussion and ask whether the initial observation has changed. Record the reason for any change so another reader can follow the evidence."],"claimIds":["interpreting-scripture-4-1","interpreting-scripture-4-2"]}],"languageNote":{"term":"Interpretation","transliteration":"Study vocabulary","meaning":"An explanation of how a passage communicates meaning in its context.","caution":"This English definition is a study aid, not a Hebrew or Greek etymology.","sourceUrl":"https://ebible.org/engwebp/LUK24.htm"},"relatedPassages":[{"reference":"2 Timothy 3:14–17","url":"https://ebible.org/engwebp/2TI03.htm"}],"consensus":"The selected Nicene traditions receive Scripture as foundational to Christian teaching; their accounts of authority, tradition, and interpretation differ.","disputed":"The authority of church tradition and interpretive offices differs among Catholic, Orthodox, and Protestant communities. This lesson supplies a method, not a ruling on those differences.","application":["Read a whole paragraph aloud twice before discussing a single verse.","Keep separate columns for observation, explanation, and application."],"reflection":["Which expectation might I be bringing to the text?","Can I identify a conclusion that needs stronger evidence?"],"discussion":["Compare two applications of Luke 24. Which step of reasoning connects each to the text?","How can leaders make space for an honest “I do not know”?"],"quiz":[{"question":"Which should come first in careful interpretation?","options":["A favorite modern application","Observation of the passage and its setting","A claim about a word’s hidden meaning"],"answer":1,"explanation":"Observation and context provide evidence for interpretation; application follows that work."},{"question":"What is a creed in this lesson?","options":["A substitute translation of the Bible","An identified historical summary of Christian faith","An undisputed explanation of every verse"],"answer":1,"explanation":"Creeds summarize a community’s confession and must be distinguished from the biblical text."}],"sources":[{"id":"luke","title":"World English Bible (Updated): Luke 24:13–35","url":"https://ebible.org/engwebp/LUK24.htm","locator":"Luke 24:13–35","category":"A"},{"id":"ccc-creeds","title":"Catechism of the Catholic Church: The Creeds","url":"https://www.vatican.va/archive/ENG0015/__P14.HTM","locator":"185–196","category":"E"}],"claims":[{"id":"interpreting-scripture-1-1","text":"Theology is disciplined reflection on God and the life of faith. In Luke’s Emmaus narrative, explanation, hospitality, recognition, and witness belong together. The disciples possess reports about Jesus but struggle to understand their meaning. The story invites a patient reading in which the biblical narrative corrects an incomplete expectation. It does not authorize a teacher to find any desired meaning behind every word.","sourceIds":["luke"],"locator":"Luke 24:13–35; editorial study method inferred from the narrative","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-1-2","text":"Begin with observation. Name the speaker and audience; notice repeated phrases, contrasts, questions, and actions. Then ask what kind of writing you are reading. A lament, a parable, a letter, and a narrative do different kinds of work. Write down what can be pointed to in the passage before offering an explanation. This practice gives other readers something they can inspect rather than asking them to trust your confidence.","sourceIds":["luke"],"locator":"Luke 24:13–35; editorial study method inferred from the narrative","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-2-1","text":"A verse belongs to a paragraph and a book before it becomes an item in a topical collection. The Emmaus travelers interpret the crucifixion through their disappointed hope for Israel’s redemption. Jesus answers within the story of Moses and the prophets. A Christian interpretation therefore asks how a passage relates to the whole biblical witness, while still respecting its original setting.","sourceIds":["luke"],"locator":"Luke 24:19–32; application distinguished from textual statement","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-2-2","text":"Move through four questions: what is present, how it functions, what conclusion the evidence supports, and what faithful response might follow. A contemporary application is a further step, not a replacement for interpretation. For example, the travelers’ hospitality can prompt reflection on welcoming strangers without becoming a promise that every guest is an unrecognized divine messenger.","sourceIds":["luke"],"locator":"Luke 24:19–32; application distinguished from textual statement","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-3-1","text":"This textbook identifies the World English Bible when it quotes Scripture. The lesson author’s explanation remains interpretation. Historical creeds and denominational statements help readers see how communities have understood the text; they must be identified as such. The Catholic Catechism describes creeds as summaries of Christian faith associated with baptism. That is evidence about a tradition’s self-understanding, not permission to label every later opinion universal.","sourceIds":["luke","ccc-creeds"],"locator":"Luke 24:33–35; Catechism 185–196; editorial pedagogy","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-3-2","text":"When evidence is incomplete, state the question. A useful group response is, “The passage says this; our explanation is this; another tradition understands it differently.” Keep notes about sources and uncertainty. End study with a response proportionate to what has been established: prayer, repentance, gratitude, further investigation, or a concrete act of love. An unresolved question can be an honest result of careful reading.","sourceIds":["luke","ccc-creeds"],"locator":"Luke 24:33–35; Catechism 185–196; editorial pedagogy","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-4-1","text":"Try the method with the travelers’ conversation. First record their stated hope and their account of the reports they heard. Next record Jesus’ response and the story’s movement toward recognition. Only then propose what the episode teaches about disappointment and understanding. This order lets another reader inspect the reasoning. If a proposed conclusion depends on something the narrative never says, identify that missing step.","sourceIds":["luke"],"locator":"Luke 24:13–35; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"interpreting-scripture-4-2","text":"A group can also compare the questions its members bring to the passage. One reader may notice sadness, another hospitality, another the role of Scripture. These observations can enrich one another without making every interpretation equally supported. Ask each reader to point to the language that prompted the observation. A leader can summarize the evidence, name a genuine disagreement, and choose a question for further study. The aim is shared attention and an honest response, not a contest to produce the most surprising meaning. Revisit the passage after discussion and ask whether the initial observation has changed. Record the reason for any change so another reader can follow the evidence.","sourceIds":["luke"],"locator":"Luke 24:13–35; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"A repeatable reading practice","steps":["Observe the passage","Read its context","Explain with evidence","Respond faithfully"]}},"omniscience":{"id":"omniscience","part":3,"title":"Known Completely by God","subtitle":"Omniscience, prayer, and the searching love of God","summary":"Psalm 139 approaches divine knowledge through prayer rather than an abstract inventory of information. Learn to distinguish the psalm’s witness from later philosophical models.","readingMinutes":10,"scripture":{"reference":"Psalms 139:1–4","text":"LORD, you have searched me, and you know me. You know my sitting down and my rising up. You perceive my thoughts from afar. You search out my path and my lying down, and are acquainted with all my ways. For there is not a word on my tongue, but behold, LORD, you know it altogether.","context":"Read the whole of Psalm 139, including its difficult verses 19–22 and final request for examination in verses 23–24. The psalm moves through divine knowledge, presence, creation, opposition to wickedness, and prayer.","url":"https://ebible.org/engwebp/PSA139.htm"},"objectives":["Describe divine knowledge as Psalm 139 presents it.","Recognize the difference between poetic testimony and a philosophical model.","Connect being known by God with honest prayer and responsibility."],"essentialQuestions":["How does the psalm’s final prayer shape its opening confession?","What does complete knowledge mean for honesty?","Which questions about knowledge and freedom remain beyond this passage?"],"sections":[{"id":"omniscience-section-1","title":"Knowledge spoken as prayer","paragraphs":["Omniscience is a theological term for God’s complete knowledge. Psalm 139 begins with an address to the LORD, moving from daily actions to thoughts and unspoken words. Its language is personal: the speaker is searched and known. The psalm does not merely argue that God possesses more information than humans. It depicts a life lived before a knowledge the speaker cannot escape or comprehend.","The confession ends with a request to be searched, tried, and led. That ending matters. If God already knows, prayer is not supplying missing information. It is an act of truthful relation, asking that one’s way be brought into the light. A group can therefore study the attribute without turning it into a technique for guessing other people’s motives. Being known by God does not make a human leader all-knowing."],"claimIds":["omniscience-1-1","omniscience-1-2"]},{"id":"omniscience-section-2","title":"Poetry, presence, and embodied life","paragraphs":["The psalm’s journeys to height, depth, distant sea, and darkness dramatize the impossibility of leaving God’s presence. Its account of formation in the womb likewise places the speaker’s embodied history before God. These images belong to Hebrew poetry as rendered by the WEB. They are not a modern anatomical account or a literal itinerary of the universe.","Read the difficult part as well as the comforting part. Verses 19–22 contain fierce opposition to the wicked. A teacher should neither delete them nor immediately turn them into a command for hostility toward a neighbor. The closing appeal for God to examine the speaker also invites scrutiny of the speaker’s own heart. This lesson offers that literary connection as an interpretation open to pastoral discussion."],"claimIds":["omniscience-2-1","omniscience-2-2"]},{"id":"omniscience-section-3","title":"The attribute and the limits of a model","paragraphs":["First John 3:19–20 speaks of God as greater than the heart and knowing all things. Its surrounding concern is confidence before God expressed in practical love. That setting helps prevent an account of divine knowledge from becoming only a source of terror. The chapter calls readers to action and truth while directing them beyond their own condemning heart.","The Baptist Faith and Message explicitly describes God’s knowledge as extending to past, present, future, and future decisions. Westminster gives a Reformed account of God’s decree alongside creaturely agency. These statements demonstrate how traditions formulate the question; they do not make a short psalm a complete philosophical treatise. Debates about timelessness, providence, and freedom require definitions and additional sources."],"claimIds":["omniscience-3-1","omniscience-3-2"]},{"id":"omniscience-section-4","title":"A truthful life before God","paragraphs":["A pastoral response may begin with honest prayer: gratitude for being seen, confession of what is concealed, or lament over what feels unbearable. The psalm provides language for this response without giving a leader permission to demand every private detail from a congregant. God’s knowledge and human access to another person’s story are different matters.","For study, place the psalm’s opening and closing side by side. Note what God knows and what the speaker requests. Then name one practice of integrity that follows: acknowledging a mistake, seeking appropriate help, or stopping an effort to manage appearances. This is an application drawn from the prayer, not an additional verse or a guarantee of immediate emotional relief."],"claimIds":["omniscience-4-1","omniscience-4-2"]},{"id":"omniscience-section-5","title":"A distinction worth preserving","paragraphs":["A leader can invite honest prayer while respecting a person’s privacy. “God knows” is not equivalent to “the group must know.” This distinction matters when a discussion concerns painful memories or sensitive relationships. The final prayer of Psalm 139 is addressed to God; it should not be turned into a demand for public disclosure. Encourage appropriate support, truthful self-examination, and consent in the way the group listens."],"claimIds":["omniscience-5-1"]}],"languageNote":{"term":"Omniscience","transliteration":"English theological vocabulary","meaning":"A doctrinal label for the completeness of divine knowledge.","caution":"The term is a later theological label, not the original-language wording of Psalm 139. The lesson does not derive a philosophical system from an alleged Hebrew root.","sourceUrl":"https://ebible.org/engwebp/PSA139.htm"},"relatedPassages":[{"reference":"1 John 3:19–24","url":"https://ebible.org/engwebp/1JN03.htm"},{"reference":"Genesis 22:12","url":"https://ebible.org/engwebp/GEN22.htm"}],"consensus":"The profile affirms God’s complete knowledge. Psalm 139 and 1 John 3 provide biblical witness; the precise relation between knowledge, time, and creaturely freedom calls for additional theological explanation.","disputed":"Christian accounts of providence, foreknowledge, and freedom vary. Statements that God “learns” or that prayer “changes God’s knowledge” need explicit definitions and confessional review rather than casual acceptance or dismissal.","application":["Pray the opening and closing of Psalm 139 with attention to their connection.","Practice truthful confession without claiming access to another person’s hidden motives."],"reflection":["What difference does being known make to my prayer?","Where am I trying to protect an appearance rather than tell the truth?"],"discussion":["Why should the difficult verses remain in a lesson about this psalm?","What is the difference between God’s knowledge and a leader’s claim to know another person?"],"quiz":[{"question":"What does Psalm 139 ask in its conclusion?","options":["That God search and lead the speaker","That the speaker become omniscient","That every philosophical dispute be resolved"],"answer":0,"explanation":"Verses 23–24 ask God to search, examine, and lead the speaker."},{"question":"What is omniscience here?","options":["A Hebrew personal name in Psalm 139","A later theological label for divine knowledge","A license to infer others’ motives"],"answer":1,"explanation":"The doctrinal label summarizes a topic; it is not the psalm’s original-language wording."}],"sources":[{"id":"psalm","title":"World English Bible (Updated): Psalms 139:1–24","url":"https://ebible.org/engwebp/PSA139.htm","locator":"Psalms 139:1–24","category":"A"},{"id":"john","title":"World English Bible (Updated): 1 John 3:16–24","url":"https://ebible.org/engwebp/1JN03.htm","locator":"1 John 3:16–24","category":"A"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"}],"claims":[{"id":"omniscience-1-1","text":"Omniscience is a theological term for God’s complete knowledge. Psalm 139 begins with an address to the LORD, moving from daily actions to thoughts and unspoken words. Its language is personal: the speaker is searched and known. The psalm does not merely argue that God possesses more information than humans. It depicts a life lived before a knowledge the speaker cannot escape or comprehend.","sourceIds":["psalm"],"locator":"Psalms 139:1–6, 23–24; theological synthesis","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-1-2","text":"The confession ends with a request to be searched, tried, and led. That ending matters. If God already knows, prayer is not supplying missing information. It is an act of truthful relation, asking that one’s way be brought into the light. A group can therefore study the attribute without turning it into a technique for guessing other people’s motives. Being known by God does not make a human leader all-knowing.","sourceIds":["psalm"],"locator":"Psalms 139:1–6, 23–24; theological synthesis","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-2-1","text":"The psalm’s journeys to height, depth, distant sea, and darkness dramatize the impossibility of leaving God’s presence. Its account of formation in the womb likewise places the speaker’s embodied history before God. These images belong to Hebrew poetry as rendered by the WEB. They are not a modern anatomical account or a literal itinerary of the universe.","sourceIds":["psalm"],"locator":"Psalms 139:7–24; literary interpretation","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-2-2","text":"Read the difficult part as well as the comforting part. Verses 19–22 contain fierce opposition to the wicked. A teacher should neither delete them nor immediately turn them into a command for hostility toward a neighbor. The closing appeal for God to examine the speaker also invites scrutiny of the speaker’s own heart. This lesson offers that literary connection as an interpretation open to pastoral discussion.","sourceIds":["psalm"],"locator":"Psalms 139:7–24; literary interpretation","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-3-1","text":"First John 3:19–20 speaks of God as greater than the heart and knowing all things. Its surrounding concern is confidence before God expressed in practical love. That setting helps prevent an account of divine knowledge from becoming only a source of terror. The chapter calls readers to action and truth while directing them beyond their own condemning heart.","sourceIds":["john","bfm","wcf"],"locator":"1 John 3:16–24; Baptist Faith and Message II; Westminster Confession II–III","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-3-2","text":"The Baptist Faith and Message explicitly describes God’s knowledge as extending to past, present, future, and future decisions. Westminster gives a Reformed account of God’s decree alongside creaturely agency. These statements demonstrate how traditions formulate the question; they do not make a short psalm a complete philosophical treatise. Debates about timelessness, providence, and freedom require definitions and additional sources.","sourceIds":["john","bfm","wcf"],"locator":"1 John 3:16–24; Baptist Faith and Message II; Westminster Confession II–III","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-4-1","text":"A pastoral response may begin with honest prayer: gratitude for being seen, confession of what is concealed, or lament over what feels unbearable. The psalm provides language for this response without giving a leader permission to demand every private detail from a congregant. God’s knowledge and human access to another person’s story are different matters.","sourceIds":["psalm","john"],"locator":"Psalms 139:1–6, 23–24; 1 John 3:18–20; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-4-2","text":"For study, place the psalm’s opening and closing side by side. Note what God knows and what the speaker requests. Then name one practice of integrity that follows: acknowledging a mistake, seeking appropriate help, or stopping an effort to manage appearances. This is an application drawn from the prayer, not an additional verse or a guarantee of immediate emotional relief.","sourceIds":["psalm","john"],"locator":"Psalms 139:1–6, 23–24; 1 John 3:18–20; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"omniscience-5-1","text":"A leader can invite honest prayer while respecting a person’s privacy. “God knows” is not equivalent to “the group must know.” This distinction matters when a discussion concerns painful memories or sensitive relationships. The final prayer of Psalm 139 is addressed to God; it should not be turned into a demand for public disclosure. Encourage appropriate support, truthful self-examination, and consent in the way the group listens.","sourceIds":["psalm","john"],"locator":"Psalms 139:23–24; 1 John 3:19–20; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"cycle","title":"The movement of Psalm 139","steps":["Known · 1–6","Never beyond presence · 7–12","Formed · 13–18","Search and lead me · 23–24"]}},"resurrection-hope":{"id":"resurrection-hope","part":13,"title":"Resurrection and Christian Hope","subtitle":"A future that gives present labor meaning","summary":"First Corinthians 15 places future resurrection within the proclamation of Christ’s resurrection. Its conclusion directs hope toward steadfast work rather than speculative date-setting.","readingMinutes":9,"scripture":{"reference":"1 Corinthians 15:20","text":"But now Christ has been raised from the dead. He became the first fruit of those who are asleep.","context":"Read 1 Corinthians 15:1–58. Paul recalls the received gospel, confronts denial of resurrection, discusses the raised body, and concludes with an exhortation to steadfast work.","url":"https://ebible.org/engwebp/1CO15.htm"},"objectives":["Connect Christian hope to the resurrection proclaimed in the chapter.","Describe the chapter’s contrast between perishable and imperishable life.","Distinguish core confession from disputed timelines."],"essentialQuestions":["Why does Paul begin by recalling the gospel?","What is the practical conclusion of this resurrection argument?","How should hope be taught beside grief?"],"sections":[{"id":"resurrection-hope-section-1","title":"Hope rests on a proclaimed event","paragraphs":["Paul begins with what he received and delivered: Christ died for sins, was buried, was raised, and appeared to witnesses. The chapter then answers the denial of resurrection among the audience. Its argument is tied to the proclamation of Christ, not to a general claim that every optimistic feeling is Christian hope.","Verse 20 calls Christ the first fruit of those who have fallen asleep. The image connects his resurrection with a future for those who belong to him. The language of sleep in this discussion is part of the chapter’s way of speaking about the dead; it should not be expanded into a complete doctrine of the intermediate state without further evidence."],"claimIds":["resurrection-hope-1-1","resurrection-hope-1-2"]},{"id":"resurrection-hope-section-2","title":"Continuity and transformation","paragraphs":["Paul uses sowing imagery and contrasts what is perishable with what is imperishable. The description of a spiritual body should be read within an argument about resurrection, rather than assumed to mean no body at all. The lesson does not supply a detailed physical reconstruction of resurrected life; the passage itself employs comparison and mystery.","The chapter’s climax speaks of change and victory over death through Jesus Christ. Romans 8 likewise connects hope with the redemption of the body and the liberation of creation. These passages offer more than a picture of escape from a worthless material world. At the same time, they do not answer every curious question about the mechanics of the future."],"claimIds":["resurrection-hope-2-1","resurrection-hope-2-2"]},{"id":"resurrection-hope-section-3","title":"Core confession and disputed schedules","paragraphs":["The Nicene tradition includes hope for resurrection and the life to come. That baseline should be distinguished from later systems of end-time chronology. The Baptist Faith and Message X and Westminster XXXII–XXXIII state particular confessional accounts; their presence in the source list does not make every detail common to all Christians.","Premillennial, amillennial, postmillennial, and other interpretive systems require careful definitions and further primary sources before comparison. This introductory lesson does not pretend to teach those systems in a sentence. It supplies a shared resurrection text and records that the fuller comparative unit remains an outline awaiting research."],"claimIds":["resurrection-hope-3-1","resurrection-hope-3-2"]},{"id":"resurrection-hope-section-4","title":"Hope beside grief and ordinary work","paragraphs":["The final exhortation in the chapter calls the community to steadfastness and abundance in the Lord’s work because their labor is not in vain. Future hope therefore has a present ethical consequence. It should not become an excuse to abandon responsibilities or manipulate people through confident predictions of dates the lesson has not established.","In pastoral care, hope can be spoken without ordering someone to stop grieving. The reality of loss and the confession of resurrection are not mutually exclusive. A practical response may be accompanying someone in grief or continuing a quiet act of service whose value is difficult to see. Such application follows the chapter’s conclusion while leaving room for the person’s actual sorrow."],"claimIds":["resurrection-hope-4-1","resurrection-hope-4-2"]},{"id":"resurrection-hope-section-5","title":"A disciplined boundary for future questions","paragraphs":["Create two lists: what the selected passages affirm and what they leave unanswered. Resurrection, transformation, victory through Christ, and the value of present labor belong in the first list. An exact calendar, an exhaustive description of resurrected appearance, or an explanation for every bereavement does not follow from this chapter. The second list is not a failure of the lesson; it identifies the limits of its evidence.","When someone asks a question from grief, respond to the person as well as to the proposition. A careful answer may be brief, followed by listening. Hope is not strengthened by pretending to know what the passage does not reveal. It can be expressed with patience, presence, and a continuing willingness to serve."],"claimIds":["resurrection-hope-5-1","resurrection-hope-5-2"]}],"languageNote":{"term":"Eschatology","transliteration":"Conventional theological label","meaning":"The doctrinal study of last things, including resurrection, judgment, and the consummation of hope.","caution":"A label does not establish a prophetic timetable. This lesson does not infer dates or certify one complete end-times system.","sourceUrl":"https://ebible.org/engwebp/1CO15.htm"},"relatedPassages":[{"reference":"Romans 8:18–25","url":"https://ebible.org/engwebp/ROM08.htm"},{"reference":"John 6:39–40","url":"https://ebible.org/engwebp/JHN06.htm"}],"consensus":"Within the Nicene profile, resurrection and the life to come are confessed. The shared confession must not be confused with complete agreement about end-time chronology.","disputed":"The millennium, sequence of final events, intermediate state, and detailed accounts of judgment differ. Comparative lessons remain research outlines, and no date-setting is authorized.","application":["Continue one ordinary work of care in light of the chapter’s conclusion.","Speak of hope in a way that allows a grieving person to tell the truth about loss."],"reflection":["Does my account of the future change how I serve now?","Can I offer presence without demanding quick emotional resolution?"],"discussion":["Why does an argument about resurrection end with work?","Which claims belong to shared confession, and which require a named interpretive system?"],"quiz":[{"question":"What is Paul’s practical conclusion in 1 Corinthians 15:58?","options":["Abandon ordinary work","Be steadfast in the Lord’s work","Calculate a date"],"answer":1,"explanation":"The chapter concludes that labor in the Lord is not in vain."},{"question":"What should be distinguished from the Nicene baseline?","options":["All hope","Detailed end-time timelines","The confession of resurrection"],"answer":1,"explanation":"Shared confession of resurrection does not imply agreement on every proposed sequence of events."}],"sources":[{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 15:1–58","url":"https://ebible.org/engwebp/1CO15.htm","locator":"1 Corinthians 15:1–58","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 8:18–25","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:18–25","category":"A"},{"id":"nicene","title":"Nicene-Constantinopolitan Creed, Orthodox Church in America presentation","url":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed","locator":"The Symbol of Faith: Nicene Creed; councils of 325 and 381","category":"D"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"}],"claims":[{"id":"resurrection-hope-1-1","text":"Paul begins with what he received and delivered: Christ died for sins, was buried, was raised, and appeared to witnesses. The chapter then answers the denial of resurrection among the audience. Its argument is tied to the proclamation of Christ, not to a general claim that every optimistic feeling is Christian hope.","sourceIds":["corinthians"],"locator":"1 Corinthians 15:1–23","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-1-2","text":"Verse 20 calls Christ the first fruit of those who have fallen asleep. The image connects his resurrection with a future for those who belong to him. The language of sleep in this discussion is part of the chapter’s way of speaking about the dead; it should not be expanded into a complete doctrine of the intermediate state without further evidence.","sourceIds":["corinthians"],"locator":"1 Corinthians 15:1–23","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-2-1","text":"Paul uses sowing imagery and contrasts what is perishable with what is imperishable. The description of a spiritual body should be read within an argument about resurrection, rather than assumed to mean no body at all. The lesson does not supply a detailed physical reconstruction of resurrected life; the passage itself employs comparison and mystery.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:35–57; Romans 8:18–25","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-2-2","text":"The chapter’s climax speaks of change and victory over death through Jesus Christ. Romans 8 likewise connects hope with the redemption of the body and the liberation of creation. These passages offer more than a picture of escape from a worthless material world. At the same time, they do not answer every curious question about the mechanics of the future.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:35–57; Romans 8:18–25","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-3-1","text":"The Nicene tradition includes hope for resurrection and the life to come. That baseline should be distinguished from later systems of end-time chronology. The Baptist Faith and Message X and Westminster XXXII–XXXIII state particular confessional accounts; their presence in the source list does not make every detail common to all Christians.","sourceIds":["nicene","bfm","wcf"],"locator":"Nicene confession; Baptist Faith and Message X; Westminster XXXII–XXXIII","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-3-2","text":"Premillennial, amillennial, postmillennial, and other interpretive systems require careful definitions and further primary sources before comparison. This introductory lesson does not pretend to teach those systems in a sentence. It supplies a shared resurrection text and records that the fuller comparative unit remains an outline awaiting research.","sourceIds":["nicene","bfm","wcf"],"locator":"Nicene confession; Baptist Faith and Message X; Westminster XXXII–XXXIII","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-4-1","text":"The final exhortation in the chapter calls the community to steadfastness and abundance in the Lord’s work because their labor is not in vain. Future hope therefore has a present ethical consequence. It should not become an excuse to abandon responsibilities or manipulate people through confident predictions of dates the lesson has not established.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:58; Romans 8:18–25; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-4-2","text":"In pastoral care, hope can be spoken without ordering someone to stop grieving. The reality of loss and the confession of resurrection are not mutually exclusive. A practical response may be accompanying someone in grief or continuing a quiet act of service whose value is difficult to see. Such application follows the chapter’s conclusion while leaving room for the person’s actual sorrow.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:58; Romans 8:18–25; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-5-1","text":"Create two lists: what the selected passages affirm and what they leave unanswered. Resurrection, transformation, victory through Christ, and the value of present labor belong in the first list. An exact calendar, an exhaustive description of resurrected appearance, or an explanation for every bereavement does not follow from this chapter. The second list is not a failure of the lesson; it identifies the limits of its evidence.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:35–58; Romans 8:23–25; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"resurrection-hope-5-2","text":"When someone asks a question from grief, respond to the person as well as to the proposition. A careful answer may be brief, followed by listening. Hope is not strengthened by pretending to know what the passage does not reveal. It can be expressed with patience, presence, and a continuing willingness to serve.","sourceIds":["corinthians","romans"],"locator":"1 Corinthians 15:35–58; Romans 8:23–25; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"Hope with a present consequence","steps":["Christ raised","Resurrection promised","Death overcome","Steadfast work now"]}},"salvation":{"id":"salvation","part":10,"title":"Salvation: Grace, Faith, and New Life","subtitle":"Received as gift, lived in a renewed community","summary":"Ephesians 2 holds together God’s mercy, salvation by grace through faith, a life of good works, and the reconciliation of a divided people. Confessional differences remain visible.","readingMinutes":12,"scripture":{"reference":"Ephesians 2:8–10","text":"for by grace you have been saved through faith, and that not of yourselves; it is the gift of God, not of works, that no one would boast. For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.","context":"Read Ephesians 2:1–22. The movement from death to life is followed by the reconciliation of Jews and Gentiles in Christ and the image of one household and holy temple.","url":"https://ebible.org/engwebp/EPH02.htm"},"objectives":["Trace the movement from human need to divine mercy in Ephesians 2.","Distinguish the source of salvation from the good works described as its goal.","Explain the chapter’s communal horizon.","Recognize differences in confessional accounts of justification and sanctification."],"essentialQuestions":["What does grace exclude as grounds for boasting?","Why must verse 10 remain beside verses 8–9?","How does reconciliation between people belong to the chapter?"],"sections":[{"id":"salvation-section-1","title":"Mercy before achievement","paragraphs":["Ephesians 2 begins by describing a condition of transgression and death. The turning point is God’s mercy and great love. The passage presents being made alive with Christ as divine action, not a reward for the morally impressive. This order gives the lesson its emphasis: grace precedes boasting about one’s achievement.","Soteriology is the conventional theological name for the study of salvation. Biblical accounts use several images, including life, reconciliation, forgiveness, and redemption. This lesson follows the images present in Ephesians 2 rather than reducing salvation to a single unexplained term. A fuller doctrine needs multiple passages and a clearly identified theological tradition."],"claimIds":["salvation-1-1","salvation-1-2"]},{"id":"salvation-section-2","title":"Grace, faith, and works in one paragraph","paragraphs":["Verses 8–9 explicitly describe salvation by grace through faith and exclude works as a basis for boasting. Verse 10 then describes believers as created in Christ Jesus for good works. A careful account preserves both statements. Removing verse 10 can make transformed life seem irrelevant; ignoring verses 8–9 can turn salvation into an achievement.","The passage’s order is an important textual observation. It does not, by itself, settle every later dispute about the precise relation of justification, sanctification, faith, love, baptism, perseverance, or merit. A beginner should learn the paragraph before being asked to adopt technical definitions. When those terms are introduced, the tradition using them must be named."],"claimIds":["salvation-2-1","salvation-2-2"]},{"id":"salvation-section-3","title":"A people brought near","paragraphs":["The second half of the chapter addresses Gentiles who were once far off. Christ is described as making peace and reconciling both groups in one body through the cross. Salvation’s horizon is therefore communal as well as personal. The chapter does not end with isolated individuals possessing a private spiritual status.","The imagery of citizenship, household, and temple gives a group several ways to consider belonging. It also challenges religious teaching that declares peace with God while nurturing hostility toward neighbors. This is a pastoral inference from the chapter’s argument; specific disputes between communities still require truth, justice, and careful attention to their history."],"claimIds":["salvation-3-1","salvation-3-2"]},{"id":"salvation-section-4","title":"Name the tradition when defining justification","paragraphs":["The Westminster Confession XI describes justification in a Reformed forensic framework and distinguishes it from sanctification. The Catholic Catechism 1987–1995 describes justification with cleansing, renewal, and participation in Christ, including baptism. These are identified witnesses that show why the same English term can function differently in different theological systems.","The comparison must not caricature one tradition as favoring morality without grace or another as making good works irrelevant. Both cited sources place divine grace centrally, while their accounts of justification and its relations differ. This preview records those differences without claiming that a short lesson resolves them. A local church must approve the account it intends to teach."],"claimIds":["salvation-4-1","salvation-4-2"]},{"id":"salvation-section-5","title":"Assurance, humility, and a concrete next step","paragraphs":["Romans 5 describes peace with God through Jesus Christ and locates divine love in Christ’s death for sinners. Read beside Ephesians, this directs attention toward God’s mercy rather than comparison with someone else’s religious performance. It is a basis for humility, not a claim that every emotional struggle disappears.","A practical response may be gratitude, repentance, or a specific work of care prepared within ordinary life. Ask a group to name the recipient of that care rather than speaking only in generalities. Refuse to use anxiety, disability, poverty, or trauma as evidence that a person has failed to receive grace. The lesson does not provide a tool for diagnosing another person’s standing before God."],"claimIds":["salvation-5-1","salvation-5-2"]},{"id":"salvation-section-6","title":"Keep the gift and the goal in view","paragraphs":["Read the paragraph once emphasizing gift and once emphasizing good works. Then explain why each reading needs the other. This practice helps a group resist both boasting in achievement and indifference to a changed life."],"claimIds":["salvation-6-1"]}],"languageNote":{"term":"Soteriology","transliteration":"Conventional theological label","meaning":"The doctrinal study of salvation and redemption.","caution":"The label does not replace the varied biblical images or settle disputed definitions of justification. No word study is offered as a shortcut around the chapter.","sourceUrl":"https://ebible.org/engwebp/EPH02.htm"},"relatedPassages":[{"reference":"Romans 5:1–11","url":"https://ebible.org/engwebp/ROM05.htm"},{"reference":"James 2:14–26","url":"https://ebible.org/engwebp/JAS02.htm"},{"reference":"Colossians 1:12–14","url":"https://ebible.org/engwebp/COL01.htm"}],"consensus":"Within the selected traditions, salvation depends on God’s grace through Jesus Christ. Ephesians explicitly excludes boasting and describes good works as a goal of new life.","disputed":"Justification, sanctification, election, perseverance, baptism, and the relation of faith and works are described differently. Westminster and Catholic sources are presented as named traditions rather than a false claim of complete agreement.","application":["Read Ephesians 2:8–10 without separating its gift and goal.","Identify one concrete act of care that follows gratitude rather than a desire to earn status.","Discuss confessional terminology with a pastor before using the lesson for membership teaching."],"reflection":["Where does comparison with others shape my religious life?","How might grace make repentance more truthful?","Whose inclusion in the household challenges my assumptions?"],"discussion":["How do verses 8–10 relate without canceling one another?","Why should the second half of the chapter remain in a lesson on salvation?","Which definitions need to be established before comparing traditions?"],"quiz":[{"question":"What does Ephesians 2 exclude?","options":["Good works as a goal of life","Boasting based on works as the ground of salvation","Every form of human response"],"answer":1,"explanation":"Verses 8–9 exclude boasting; verse 10 names good works as the goal of being created in Christ."},{"question":"What follows the grace-and-faith paragraph?","options":["The reconciliation of divided peoples in Christ","A claim that community is irrelevant","A completed list of every later doctrine"],"answer":0,"explanation":"Ephesians 2:11–22 describes peace, reconciliation, household, and temple."},{"question":"Why identify confessional sources?","options":["To pretend differences are only vocabulary","To let readers inspect specific accounts and their differences","To replace the biblical text"],"answer":1,"explanation":"Named sources keep a comparison fair and make local pastoral review possible."}],"sources":[{"id":"ephesians","title":"World English Bible (Updated): Ephesians 2:1–22","url":"https://ebible.org/engwebp/EPH02.htm","locator":"Ephesians 2:1–22","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 5:1–11","url":"https://ebible.org/engwebp/ROM05.htm","locator":"Romans 5:1–11","category":"A"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"},{"id":"ccc-grace","title":"Catechism of the Catholic Church: Justification","url":"https://www.vatican.va/archive/ENG0015/__P6Y.HTM","locator":"1987–1995","category":"E"}],"claims":[{"id":"salvation-1-1","text":"Ephesians 2 begins by describing a condition of transgression and death. The turning point is God’s mercy and great love. The passage presents being made alive with Christ as divine action, not a reward for the morally impressive. This order gives the lesson its emphasis: grace precedes boasting about one’s achievement.","sourceIds":["ephesians"],"locator":"Ephesians 2:1–10; doctrinal topic label","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-1-2","text":"Soteriology is the conventional theological name for the study of salvation. Biblical accounts use several images, including life, reconciliation, forgiveness, and redemption. This lesson follows the images present in Ephesians 2 rather than reducing salvation to a single unexplained term. A fuller doctrine needs multiple passages and a clearly identified theological tradition.","sourceIds":["ephesians"],"locator":"Ephesians 2:1–10; doctrinal topic label","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-2-1","text":"Verses 8–9 explicitly describe salvation by grace through faith and exclude works as a basis for boasting. Verse 10 then describes believers as created in Christ Jesus for good works. A careful account preserves both statements. Removing verse 10 can make transformed life seem irrelevant; ignoring verses 8–9 can turn salvation into an achievement.","sourceIds":["ephesians"],"locator":"Ephesians 2:8–10; limits on doctrinal inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-2-2","text":"The passage’s order is an important textual observation. It does not, by itself, settle every later dispute about the precise relation of justification, sanctification, faith, love, baptism, perseverance, or merit. A beginner should learn the paragraph before being asked to adopt technical definitions. When those terms are introduced, the tradition using them must be named.","sourceIds":["ephesians"],"locator":"Ephesians 2:8–10; limits on doctrinal inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-3-1","text":"The second half of the chapter addresses Gentiles who were once far off. Christ is described as making peace and reconciling both groups in one body through the cross. Salvation’s horizon is therefore communal as well as personal. The chapter does not end with isolated individuals possessing a private spiritual status.","sourceIds":["ephesians"],"locator":"Ephesians 2:11–22; pastoral inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-3-2","text":"The imagery of citizenship, household, and temple gives a group several ways to consider belonging. It also challenges religious teaching that declares peace with God while nurturing hostility toward neighbors. This is a pastoral inference from the chapter’s argument; specific disputes between communities still require truth, justice, and careful attention to their history.","sourceIds":["ephesians"],"locator":"Ephesians 2:11–22; pastoral inference","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-4-1","text":"The Westminster Confession XI describes justification in a Reformed forensic framework and distinguishes it from sanctification. The Catholic Catechism 1987–1995 describes justification with cleansing, renewal, and participation in Christ, including baptism. These are identified witnesses that show why the same English term can function differently in different theological systems.","sourceIds":["wcf","ccc-grace","ephesians"],"locator":"Westminster XI–XIII; Catechism 1987–1995; Ephesians 2:8–10","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-4-2","text":"The comparison must not caricature one tradition as favoring morality without grace or another as making good works irrelevant. Both cited sources place divine grace centrally, while their accounts of justification and its relations differ. This preview records those differences without claiming that a short lesson resolves them. A local church must approve the account it intends to teach.","sourceIds":["wcf","ccc-grace","ephesians"],"locator":"Westminster XI–XIII; Catechism 1987–1995; Ephesians 2:8–10","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-5-1","text":"Romans 5 describes peace with God through Jesus Christ and locates divine love in Christ’s death for sinners. Read beside Ephesians, this directs attention toward God’s mercy rather than comparison with someone else’s religious performance. It is a basis for humility, not a claim that every emotional struggle disappears.","sourceIds":["romans","ephesians"],"locator":"Romans 5:1–11; Ephesians 2:8–10; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-5-2","text":"A practical response may be gratitude, repentance, or a specific work of care prepared within ordinary life. Ask a group to name the recipient of that care rather than speaking only in generalities. Refuse to use anxiety, disability, poverty, or trauma as evidence that a person has failed to receive grace. The lesson does not provide a tool for diagnosing another person’s standing before God.","sourceIds":["romans","ephesians"],"locator":"Romans 5:1–11; Ephesians 2:8–10; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"salvation-6-1","text":"Read the paragraph once emphasizing gift and once emphasizing good works. Then explain why each reading needs the other. This practice helps a group resist both boasting in achievement and indifference to a changed life.","sourceIds":["ephesians"],"locator":"Ephesians 2:8–10; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"The movement of Ephesians 2","steps":["Need · 1–3","Mercy and grace · 4–9","New life and works · 10","One reconciled household · 11–22"]}},"scripture":{"id":"scripture","part":2,"title":"The Doctrine of Scripture","subtitle":"God-breathed writings that form a faithful people","summary":"Read 2 Timothy’s teaching about Scripture in its pastoral setting, with care for inspiration, purpose, canon, and the distinction between text and interpretation.","readingMinutes":10,"scripture":{"reference":"2 Timothy 3:16–17","text":"Every Scripture is God-breathed and profitable for teaching, for reproof, for correction, and for instruction in righteousness, that each person who belongs to God may be complete, thoroughly equipped for every good work.","context":"Read 2 Timothy 3:10–17. A call to remain in received teaching follows descriptions of persecution, deception, and Timothy’s acquaintance with the sacred writings from childhood.","url":"https://ebible.org/engwebp/2TI03.htm"},"objectives":["Explain Scripture’s stated purposes in 2 Timothy 3.","Distinguish inspiration, interpretation, translation, and canon.","Identify this application’s selected edition and limits."],"essentialQuestions":["What is Scripture intended to do in the community?","Does a doctrine of inspiration make every interpretation infallible?","Why should a textbook disclose its canon and translation?"],"sections":[{"id":"scripture-section-1","title":"A pastoral setting before a doctrinal formula","paragraphs":["The passage addresses a learner who has encountered suffering and misleading teaching. Its instruction about Scripture is connected to perseverance, salvation through faith in Christ, and the formation of a person equipped for good work. Reading only verse 16 can hide this purpose. The text does not introduce inspiration as a puzzle detached from worship and conduct.","The WEB renders verse 16 with “God-breathed” and notes an alternative construction in its footnote. This lesson follows the main WEB wording and records that a translation decision exists. Inspiration concerns Scripture’s relation to God; interpretation concerns how a reader understands what is written. A strong claim about inspiration does not establish the accuracy of every sermon, marginal note, or digital summary."],"claimIds":["scripture-1-1","scripture-1-2"]},{"id":"scripture-section-2","title":"Four purposes and a living outcome","paragraphs":["Teaching communicates what the community is to learn. Reproof exposes error; correction turns a learner toward what is right; training in righteousness describes ongoing formation. Verse 17 names an outcome: readiness for good work. In a study group, ask whether a discussion has served these purposes or merely produced an argument. The passage warrants a close relation between learning and practice.","The sacred writings Timothy knew in childhood belong to the scriptural world in which this letter speaks. The two verses do not themselves provide a table of contents for the later Christian Bible. Canon describes the collection a community receives as Scripture. This preview uses the updated WEB 66-book protocanon. That technical choice must not imply that Catholic and Orthodox canons are identical to a Protestant canon."],"claimIds":["scripture-2-1","scripture-2-2"]},{"id":"scripture-section-3","title":"Authority with accountable interpretation","paragraphs":["The Baptist Faith and Message and Westminster Confession articulate Protestant accounts of Scripture’s authority. These are denominational witnesses, not neutral replacements for the passage. Readers from other traditions should be able to identify where a confessional position is being described. A local church must review the profile before treating this textbook as its teaching material.","Use a translation honestly. Quotation marks indicate the exact selected text; an explanation or simplification should be labeled as such. Consult the full paragraph when a phrase seems surprising and compare textual notes rather than silently editing them away. Digital search is helpful for finding passages, but a search result is an entry into reading, not the completion of interpretation."],"claimIds":["scripture-3-1","scripture-3-2"]},{"id":"scripture-section-4","title":"A source-conscious study session","paragraphs":["For a practical exercise, place the quotation from verses 16–17 beside the lesson’s explanation. Highlight the exact biblical words in one color and interpretive conclusions in another. Then ask which conclusions are directly supported by the paragraph and which require additional passages. This exercise protects Scripture’s authority by refusing to transfer it automatically to the lesson author. A digital resource should make that distinction easier to see.","Next inspect a confessional statement’s account of Scripture. Record its community and section number rather than introducing it simply as “what Christians believe.” The Baptist and Westminster documents are useful because their provenance is identifiable and their wording can be checked. If a learner belongs to a different tradition, the appropriate response is to locate that tradition’s official teaching, not to assume that a Protestant document speaks for it.","Finally choose one of the passage’s purposes and describe a fitting response. A correction may involve changing a habit; instruction may require further learning; readiness for good work may involve helping a neighbor. The action should follow the passage’s content rather than being attached as a generic moral at the end. Keep the group’s notes so a pastor or editor can review the route from quotation to explanation to application."],"claimIds":["scripture-4-1","scripture-4-2","scripture-4-3"]}],"languageNote":{"term":"God-breathed","transliteration":"WEB translation wording","meaning":"The WEB’s rendering in 2 Timothy 3:16 describes Scripture’s relation to God.","caution":"The WEB footnote records an alternative construction. No conclusion about canon or translation perfection follows from the English phrase alone.","sourceUrl":"https://ebible.org/engwebp/2TI03.htm"},"relatedPassages":[{"reference":"Luke 24:44–49","url":"https://ebible.org/engwebp/LUK24.htm"},{"reference":"John 17:17","url":"https://ebible.org/engwebp/JHN17.htm"}],"consensus":"The Nicene educational profile receives Scripture as a primary witness for Christian doctrine. This does not settle every tradition’s account of canon, inspiration, or interpretive authority.","disputed":"Protestant accounts of Scripture as the supreme standard, and Catholic or Orthodox accounts of Scripture within apostolic tradition, require separate confessional review. “Inerrancy” and “infallibility” should be defined before comparison.","application":["Choose one purpose from verses 16–17 and identify an appropriate response to the paragraph.","Label a quotation, paraphrase, and doctrinal inference differently in your study notes."],"reflection":["How has Scripture corrected me as well as comforted me?","Have I confused my certainty with the text’s authority?"],"discussion":["How would a group study change if its goal were readiness for good work?","Why is disclosing the translation and canon an act of care for readers?"],"quiz":[{"question":"What outcome does 2 Timothy 3:17 describe?","options":["Mastery of every future controversy","Being equipped for every good work","A completed list of biblical books"],"answer":1,"explanation":"The stated purpose is the formation and equipping of the person who belongs to God."},{"question":"Which statement is accurate about this preview?","options":["Every church uses its exact canon","It quotes the updated WEB 66-book edition","Its interpretation has church approval"],"answer":1,"explanation":"The translation and canon are declared technical and editorial choices awaiting local confirmation."}],"sources":[{"id":"timothy","title":"World English Bible (Updated): 2 Timothy 3:10–17","url":"https://ebible.org/engwebp/2TI03.htm","locator":"2 Timothy 3:10–17","category":"A"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"}],"claims":[{"id":"scripture-1-1","text":"The passage addresses a learner who has encountered suffering and misleading teaching. Its instruction about Scripture is connected to perseverance, salvation through faith in Christ, and the formation of a person equipped for good work. Reading only verse 16 can hide this purpose. The text does not introduce inspiration as a puzzle detached from worship and conduct.","sourceIds":["timothy"],"locator":"2 Timothy 3:10–17; translation footnote to 3:16","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-1-2","text":"The WEB renders verse 16 with “God-breathed” and notes an alternative construction in its footnote. This lesson follows the main WEB wording and records that a translation decision exists. Inspiration concerns Scripture’s relation to God; interpretation concerns how a reader understands what is written. A strong claim about inspiration does not establish the accuracy of every sermon, marginal note, or digital summary.","sourceIds":["timothy"],"locator":"2 Timothy 3:10–17; translation footnote to 3:16","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-2-1","text":"Teaching communicates what the community is to learn. Reproof exposes error; correction turns a learner toward what is right; training in righteousness describes ongoing formation. Verse 17 names an outcome: readiness for good work. In a study group, ask whether a discussion has served these purposes or merely produced an argument. The passage warrants a close relation between learning and practice.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster Confession I; WEB edition footer","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-2-2","text":"The sacred writings Timothy knew in childhood belong to the scriptural world in which this letter speaks. The two verses do not themselves provide a table of contents for the later Christian Bible. Canon describes the collection a community receives as Scripture. This preview uses the updated WEB 66-book protocanon. That technical choice must not imply that Catholic and Orthodox canons are identical to a Protestant canon.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster Confession I; WEB edition footer","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-3-1","text":"The Baptist Faith and Message and Westminster Confession articulate Protestant accounts of Scripture’s authority. These are denominational witnesses, not neutral replacements for the passage. Readers from other traditions should be able to identify where a confessional position is being described. A local church must review the profile before treating this textbook as its teaching material.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster Confession I","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-3-2","text":"Use a translation honestly. Quotation marks indicate the exact selected text; an explanation or simplification should be labeled as such. Consult the full paragraph when a phrase seems surprising and compare textual notes rather than silently editing them away. Digital search is helpful for finding passages, but a search result is an entry into reading, not the completion of interpretation.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster Confession I","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-4-1","text":"For a practical exercise, place the quotation from verses 16–17 beside the lesson’s explanation. Highlight the exact biblical words in one color and interpretive conclusions in another. Then ask which conclusions are directly supported by the paragraph and which require additional passages. This exercise protects Scripture’s authority by refusing to transfer it automatically to the lesson author. A digital resource should make that distinction easier to see.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster I; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-4-2","text":"Next inspect a confessional statement’s account of Scripture. Record its community and section number rather than introducing it simply as “what Christians believe.” The Baptist and Westminster documents are useful because their provenance is identifiable and their wording can be checked. If a learner belongs to a different tradition, the appropriate response is to locate that tradition’s official teaching, not to assume that a Protestant document speaks for it.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster I; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"scripture-4-3","text":"Finally choose one of the passage’s purposes and describe a fitting response. A correction may involve changing a habit; instruction may require further learning; readiness for good work may involve helping a neighbor. The action should follow the passage’s content rather than being attached as a generic moral at the end. Keep the group’s notes so a pastor or editor can review the route from quotation to explanation to application.","sourceIds":["timothy","bfm","wcf"],"locator":"2 Timothy 3:14–17; Baptist Faith and Message I; Westminster I; original teaching exercise","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"Scripture’s formative purposes","steps":["Teaching","Reproof","Correction","Training → good work"]}},"sin-and-grace":{"id":"sin-and-grace","part":7,"title":"Sin and the Need for Grace","subtitle":"Facing a broken condition without losing sight of mercy","summary":"Romans 5 places the reach of sin and death beside the greater gift in Christ. Learn to name personal and shared wrong without turning doctrine into shame or fatalism.","readingMinutes":9,"scripture":{"reference":"Romans 5:8","text":"But God commends his own love toward us, in that while we were yet sinners, Christ died for us.","context":"Read Romans 5:1–21. Paul moves from peace and hope through Christ to a comparison between Adam’s trespass and the gift associated with Christ’s obedience.","url":"https://ebible.org/engwebp/ROM05.htm"},"objectives":["Describe the connection between sin, death, and grace in Romans 5.","Distinguish the passage’s comparison from later accounts of inherited sin.","Name wrongdoing without denying the possibility of repentance and mercy."],"essentialQuestions":["How does Paul describe the reach of sin?","Why must the gift in Christ remain central to this chapter?","What is the difference between conviction and dehumanizing shame?"],"sections":[{"id":"sin-and-grace-section-1","title":"Read the diagnosis beside the gift","paragraphs":["Romans 5 does not describe sin in isolation from God’s reconciling action. It begins with peace, access to grace, and hope, then speaks of Christ dying for the ungodly. The selected verse portrays love acting while people are still sinners. A lesson that names only human failure and never reaches this context would misrepresent the chapter’s movement.","Hamartiology is the conventional label for the doctrine of sin. The label should not become a way to avoid concrete moral reality. Sin concerns wrong in relation to God and neighbor, while Romans 5 also portrays a condition marked by death. The chapter’s Adam–Christ comparison invites a larger view than a list of isolated mistakes."],"claimIds":["sin-and-grace-1-1","sin-and-grace-1-2"]},{"id":"sin-and-grace-section-2","title":"Adam, humanity, and Christ","paragraphs":["Paul compares the entrance of sin and death through one man with the gift and life associated with Jesus Christ. He also insists that the gift is not simply equivalent to the trespass. Read the repeated contrasts and the repeated language of abundance. The comparison is meant to magnify grace rather than produce an even balance between two equal powers.","Christians have developed different accounts of inherited guilt, corruption, ancestral sin, and human responsibility. Westminster VI provides a particular Reformed formulation. The Baptist Faith and Message III offers another identified confessional account. This introductory lesson does not silently place either formulation into Paul’s mouth as though its later vocabulary were a direct quotation."],"claimIds":["sin-and-grace-2-1","sin-and-grace-2-2"]},{"id":"sin-and-grace-section-3","title":"Responsibility without fatalism","paragraphs":["Describing sin as widespread should not make wrongdoing inevitable in a way that excuses it. The passage contrasts the reign of sin with grace through Jesus Christ. A responsible application asks where repentance, repair, and a different pattern of life are needed. “Everyone does it” is not a satisfactory moral response.","Likewise, a doctrine of sin should not be used to tell someone that abuse suffered was deserved or that another person’s violence can be ignored. The fact that a community speaks about universal need does not erase differences between perpetrating harm and being harmed. Pastoral care must attend to the concrete situation and keep protection, truth, and accountability in view."],"claimIds":["sin-and-grace-3-1","sin-and-grace-3-2"]},{"id":"sin-and-grace-section-4","title":"Confession and repair","paragraphs":["Begin with a specific admission rather than a global declaration of worthlessness. Name what was done, who was affected, and what repair is possible. Reconciliation can require restitution and appropriate boundaries; a religious phrase should not replace those steps. These are practical applications of taking wrong and mercy seriously, not a complete formula supplied by Romans 5.","For group study, put the chapter’s contrasts in two columns and notice where Paul says “much more.” End by asking how grace can make truthful confession possible. The goal is neither moral self-exemption nor endless self-condemnation, but a response to a mercy that does not depend on pretending there was no wrong."],"claimIds":["sin-and-grace-4-1","sin-and-grace-4-2"]},{"id":"sin-and-grace-section-5","title":"Tell the truth without turning people into labels","paragraphs":["In discussion, distinguish naming an action from reducing a person to the worst thing associated with them. The chapter’s account of reconciliation invites a response that takes wrong seriously while refusing to make it the only possible future. This does not require immediate restoration to a position of trust or the removal of consequences. Those decisions need careful attention to safety and accountability.","A useful exercise is to write a specific admission without an excuse and then identify what repair would involve. Another person’s forgiveness cannot be controlled by the offender. Grace is not a mechanism for forcing a harmed person to reconcile on a timetable. The lesson’s task is to connect mercy with truth rather than using either to conceal the other."],"claimIds":["sin-and-grace-5-1","sin-and-grace-5-2"]}],"languageNote":{"term":"Hamartiology","transliteration":"Conventional theological label","meaning":"The doctrinal study of sin.","caution":"This label is not an etymological argument that reduces every biblical description of sin to “missing the mark.” Context and the full range of biblical language matter.","sourceUrl":"https://ebible.org/engwebp/ROM05.htm"},"relatedPassages":[{"reference":"Ephesians 2:1–10","url":"https://ebible.org/engwebp/EPH02.htm"},{"reference":"1 John 3:4–10","url":"https://ebible.org/engwebp/1JN03.htm"}],"consensus":"The selected Nicene traditions confess the need for divine grace and redemption in Christ. Romans 5 explicitly juxtaposes sin and death with the gift and life through Christ.","disputed":"Inherited guilt, ancestral sin, original corruption, and the effects of the fall are described differently across traditions. Local doctrine must be confirmed before this preview serves as a church statement.","application":["Make a specific confession and consider proportionate repair.","Refuse to use universal sinfulness to minimize a particular act of abuse."],"reflection":["Where do I use general language to avoid a specific admission?","Does my account of sin leave room for the abundance of grace?"],"discussion":["What does Paul’s “not like” contrast contribute?","How can a group discuss wrongdoing without silencing those who have been harmed?"],"quiz":[{"question":"When does Romans 5:8 say Christ died for us?","options":["After we became morally complete","While we were still sinners","Only after every consequence disappeared"],"answer":1,"explanation":"The verse locates the demonstration of love while people are still sinners."},{"question":"What should an introduction distinguish?","options":["Paul’s argument and later confessional formulations","Scripture and all moral responsibility","Grace and any need for truth"],"answer":0,"explanation":"Later doctrinal formulations interpret the passage and should be identified honestly."}],"sources":[{"id":"romans","title":"World English Bible (Updated): Romans 5:1–21","url":"https://ebible.org/engwebp/ROM05.htm","locator":"Romans 5:1–21","category":"A"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"}],"claims":[{"id":"sin-and-grace-1-1","text":"Romans 5 does not describe sin in isolation from God’s reconciling action. It begins with peace, access to grace, and hope, then speaks of Christ dying for the ungodly. The selected verse portrays love acting while people are still sinners. A lesson that names only human failure and never reaches this context would misrepresent the chapter’s movement.","sourceIds":["romans"],"locator":"Romans 5:1–12; theological topic label identified as conventional","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-1-2","text":"Hamartiology is the conventional label for the doctrine of sin. The label should not become a way to avoid concrete moral reality. Sin concerns wrong in relation to God and neighbor, while Romans 5 also portrays a condition marked by death. The chapter’s Adam–Christ comparison invites a larger view than a list of isolated mistakes.","sourceIds":["romans"],"locator":"Romans 5:1–12; theological topic label identified as conventional","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-2-1","text":"Paul compares the entrance of sin and death through one man with the gift and life associated with Jesus Christ. He also insists that the gift is not simply equivalent to the trespass. Read the repeated contrasts and the repeated language of abundance. The comparison is meant to magnify grace rather than produce an even balance between two equal powers.","sourceIds":["romans","wcf","bfm"],"locator":"Romans 5:12–21; Westminster VI; Baptist Faith and Message III","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-2-2","text":"Christians have developed different accounts of inherited guilt, corruption, ancestral sin, and human responsibility. Westminster VI provides a particular Reformed formulation. The Baptist Faith and Message III offers another identified confessional account. This introductory lesson does not silently place either formulation into Paul’s mouth as though its later vocabulary were a direct quotation.","sourceIds":["romans","wcf","bfm"],"locator":"Romans 5:12–21; Westminster VI; Baptist Faith and Message III","category":"E","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-3-1","text":"Describing sin as widespread should not make wrongdoing inevitable in a way that excuses it. The passage contrasts the reign of sin with grace through Jesus Christ. A responsible application asks where repentance, repair, and a different pattern of life are needed. “Everyone does it” is not a satisfactory moral response.","sourceIds":["romans"],"locator":"Romans 5:6–11, 20–21; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-3-2","text":"Likewise, a doctrine of sin should not be used to tell someone that abuse suffered was deserved or that another person’s violence can be ignored. The fact that a community speaks about universal need does not erase differences between perpetrating harm and being harmed. Pastoral care must attend to the concrete situation and keep protection, truth, and accountability in view.","sourceIds":["romans"],"locator":"Romans 5:6–11, 20–21; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-4-1","text":"Begin with a specific admission rather than a global declaration of worthlessness. Name what was done, who was affected, and what repair is possible. Reconciliation can require restitution and appropriate boundaries; a religious phrase should not replace those steps. These are practical applications of taking wrong and mercy seriously, not a complete formula supplied by Romans 5.","sourceIds":["romans"],"locator":"Romans 5:8–11, 15–21; pastoral reflection","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-4-2","text":"For group study, put the chapter’s contrasts in two columns and notice where Paul says “much more.” End by asking how grace can make truthful confession possible. The goal is neither moral self-exemption nor endless self-condemnation, but a response to a mercy that does not depend on pretending there was no wrong.","sourceIds":["romans"],"locator":"Romans 5:8–11, 15–21; pastoral reflection","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-5-1","text":"In discussion, distinguish naming an action from reducing a person to the worst thing associated with them. The chapter’s account of reconciliation invites a response that takes wrong seriously while refusing to make it the only possible future. This does not require immediate restoration to a position of trust or the removal of consequences. Those decisions need careful attention to safety and accountability.","sourceIds":["romans"],"locator":"Romans 5:6–11, 15–21; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"sin-and-grace-5-2","text":"A useful exercise is to write a specific admission without an excuse and then identify what repair would involve. Another person’s forgiveness cannot be controlled by the offender. Grace is not a mechanism for forcing a harmed person to reconcile on a timetable. The lesson’s task is to connect mercy with truth rather than using either to conceal the other.","sourceIds":["romans"],"locator":"Romans 5:6–11, 15–21; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"comparison","title":"Paul’s comparison in Romans 5","steps":["Adam: trespass","Sin and death","Christ: gift","Grace and life"]}},"trinity":{"id":"trinity","part":4,"title":"One God: Father, Son, and Holy Spirit","subtitle":"Learning the grammar of Nicene confession","summary":"The baptismal commission and the Nicene tradition teach Christians to confess one God while distinguishing Father, Son, and Holy Spirit. Simple analogies require care.","readingMinutes":9,"scripture":{"reference":"Matthew 28:18–20","text":"Jesus came to them and spoke to them, saying, “All authority has been given to me in heaven and on earth. Go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, teaching them to observe all things that I commanded you. Behold, I am with you always, even to the end of the age.” Amen.","context":"Read Matthew 28:16–20. The risen Jesus meets the eleven in Galilee, speaks of his authority, and commissions their teaching and baptism.","url":"https://ebible.org/engwebp/MAT28.htm"},"objectives":["Identify the three named in Matthew’s baptismal commission.","Explain the distinction between biblical wording and later doctrinal formulation.","Recognize the limits of familiar analogies."],"essentialQuestions":["Why does Nicene theology distinguish person and divine being?","What does a diagram help us remember, and what can it distort?","How does confession shape baptism and worship?"],"sections":[{"id":"trinity-section-1","title":"The biblical starting point","paragraphs":["Matthew ends with a commission grounded in Jesus’ authority and accompanied by his promised presence. Baptism is described in relation to Father, Son, and Holy Spirit. This is a biblical foundation for Trinitarian teaching, but the passage is not a dictionary defining every term that later theologians use. Reading it responsibly means keeping its mission and teaching setting visible.","John 17 presents Jesus praying to the Father, speaking of the glory he had with the Father before the world existed. The narrative distinguishes the one praying from the one addressed. This witness belongs in a broader biblical account rather than being forced into a single-verse demonstration that ignores the actual relationship portrayed."],"claimIds":["trinity-1-1","trinity-1-2"]},{"id":"trinity-section-2","title":"A historical confession with a careful vocabulary","paragraphs":["The Nicene-Constantinopolitan tradition confesses one God and speaks of Father, Son, and Holy Spirit. Its received formulation is associated with the councils of 325 and 381. The OCA presentation and Catholic Catechism identify this conciliar setting. This textbook’s broadly Nicene profile follows that tradition for educational purposes; it does not claim that all religious groups accept it.","In this doctrinal vocabulary, “person” distinguishes Father, Son, and Spirit; “being” or “essence” concerns the one divine reality. These terms serve the confession rather than turning God into an object that can be completely described. A beginner should first learn what the formulation protects: the unity of God and the distinction of Father, Son, and Spirit. Technical historical questions can follow with further reading."],"claimIds":["trinity-2-1","trinity-2-2"]},{"id":"trinity-section-3","title":"Diagrams are reminders, not explanations of God","paragraphs":["A triangle can help a learner remember three named persons, but it cannot explain divine life. Water changing among ice, liquid, and steam can suggest that one individual merely changes roles. Three separate human beings can suggest three gods. The point is not to replace one imperfect picture with a supposedly perfect picture; it is to keep the confession’s boundaries clear.","The visual in this lesson is a comparison aid: one God; Father, Son, and Spirit distinguished; one confession in baptism and worship. It is original teaching art, not a historically authoritative depiction. Ask learners to repeat the doctrinal statement in words so the visual does not carry more meaning than the text supports."],"claimIds":["trinity-3-1","trinity-3-2"]},{"id":"trinity-section-4","title":"Confession in the life of faith","paragraphs":["The baptismal setting joins learning to discipleship. A Trinitarian lesson is incomplete if it leaves readers only with a diagram and no attention to worship, prayer, and obedient teaching. The commission includes observing what Jesus commanded. A group may therefore examine whether its teaching cultivates the life to which the passage calls it.","Differences about the procession of the Spirit and the later Western addition to the creed require historical precision. This preview does not silently choose one wording as though every church uses it. Before local adoption, a pastor should confirm the church’s received creed and preferred terminology. Honest identification of that decision makes shared learning possible."],"claimIds":["trinity-4-1","trinity-4-2"]},{"id":"trinity-section-5","title":"Practice the distinction in words","paragraphs":["Invite learners to identify the difference between the biblical sentence and the doctrinal summary. Matthew supplies the baptismal naming of Father, Son, and Spirit within a commission. The Nicene formulation supplies a received way of confessing the divine unity and distinction. Both can be studied closely without pretending that their genres are identical. A helpful teaching session allows a learner to say which kind of statement is being made and why it matters.","If a question reaches beyond the lesson, record it rather than improvising an answer. Terms about eternal relations, procession, and the history of conciliar language deserve more than an analogy offered under pressure. Careful limits model reverence and give a pastor a clear starting point for further teaching."],"claimIds":["trinity-5-1","trinity-5-2"]}],"languageNote":{"term":"Trinity","transliteration":"Later Christian doctrinal terminology","meaning":"A theological name for the confession of the one God as Father, Son, and Holy Spirit.","caution":"The English word is not a quotation from Matthew 28. It names a doctrinal synthesis, not an independently verified Greek etymology.","sourceUrl":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed"},"relatedPassages":[{"reference":"John 17:1–5","url":"https://ebible.org/engwebp/JHN17.htm"},{"reference":"1 Corinthians 12:4–6","url":"https://ebible.org/engwebp/1CO12.htm"}],"consensus":"Within the declared Nicene profile, one God is confessed as Father, Son, and Holy Spirit. This is a defined confessional baseline, not a claim of agreement among all religious communities.","disputed":"Eastern and Western traditions differ over the Filioque and its authority. Technical accounts of persons and relations also need specialist review; no diagram resolves these differences.","application":["Read the baptismal commission as a call to teaching and life together.","Evaluate an analogy by what it risks implying, not only by how memorable it is."],"reflection":["Can I distinguish biblical wording from the doctrinal terms used to explain it?","How does confession shape the way I pray?"],"discussion":["Why might a vivid analogy teach an unintended idea?","Which received wording of the creed does your church use?"],"quiz":[{"question":"Who is named in Matthew 28:19?","options":["Abraham, Isaac, and Jacob","Father, Son, and Holy Spirit","Three independent deities"],"answer":1,"explanation":"Matthew names Father, Son, and Holy Spirit in the baptismal commission."},{"question":"What status does the lesson’s diagram have?","options":["A complete account of God","An original teaching reminder with limits","An inspired addition to Matthew"],"answer":1,"explanation":"A diagram supports memory and must remain subordinate to textual and doctrinal explanation."}],"sources":[{"id":"matthew","title":"World English Bible (Updated): Matthew 28:16–20","url":"https://ebible.org/engwebp/MAT28.htm","locator":"Matthew 28:16–20","category":"A"},{"id":"john","title":"World English Bible (Updated): John 17:1–5","url":"https://ebible.org/engwebp/JHN17.htm","locator":"John 17:1–5","category":"A"},{"id":"nicene","title":"Nicene-Constantinopolitan Creed, Orthodox Church in America presentation","url":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed","locator":"The Symbol of Faith: Nicene Creed; councils of 325 and 381","category":"D"},{"id":"ccc-creeds","title":"Catechism of the Catholic Church: The Creeds","url":"https://www.vatican.va/archive/ENG0015/__P14.HTM","locator":"185–196","category":"E"}],"claims":[{"id":"trinity-1-1","text":"Matthew ends with a commission grounded in Jesus’ authority and accompanied by his promised presence. Baptism is described in relation to Father, Son, and Holy Spirit. This is a biblical foundation for Trinitarian teaching, but the passage is not a dictionary defining every term that later theologians use. Reading it responsibly means keeping its mission and teaching setting visible.","sourceIds":["matthew","john"],"locator":"Matthew 28:16–20; John 17:1–5","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-1-2","text":"John 17 presents Jesus praying to the Father, speaking of the glory he had with the Father before the world existed. The narrative distinguishes the one praying from the one addressed. This witness belongs in a broader biblical account rather than being forced into a single-verse demonstration that ignores the actual relationship portrayed.","sourceIds":["matthew","john"],"locator":"Matthew 28:16–20; John 17:1–5","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-2-1","text":"The Nicene-Constantinopolitan tradition confesses one God and speaks of Father, Son, and Holy Spirit. Its received formulation is associated with the councils of 325 and 381. The OCA presentation and Catholic Catechism identify this conciliar setting. This textbook’s broadly Nicene profile follows that tradition for educational purposes; it does not claim that all religious groups accept it.","sourceIds":["nicene","ccc-creeds"],"locator":"Nicene Creed presentation; Catechism 189–195","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-2-2","text":"In this doctrinal vocabulary, “person” distinguishes Father, Son, and Spirit; “being” or “essence” concerns the one divine reality. These terms serve the confession rather than turning God into an object that can be completely described. A beginner should first learn what the formulation protects: the unity of God and the distinction of Father, Son, and Spirit. Technical historical questions can follow with further reading.","sourceIds":["nicene","ccc-creeds"],"locator":"Nicene Creed presentation; Catechism 189–195","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-3-1","text":"A triangle can help a learner remember three named persons, but it cannot explain divine life. Water changing among ice, liquid, and steam can suggest that one individual merely changes roles. Three separate human beings can suggest three gods. The point is not to replace one imperfect picture with a supposedly perfect picture; it is to keep the confession’s boundaries clear.","sourceIds":["nicene","matthew"],"locator":"Nicene confession and Matthew 28:19; editorial limits on analogies","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-3-2","text":"The visual in this lesson is a comparison aid: one God; Father, Son, and Spirit distinguished; one confession in baptism and worship. It is original teaching art, not a historically authoritative depiction. Ask learners to repeat the doctrinal statement in words so the visual does not carry more meaning than the text supports.","sourceIds":["nicene","matthew"],"locator":"Nicene confession and Matthew 28:19; editorial limits on analogies","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-4-1","text":"The baptismal setting joins learning to discipleship. A Trinitarian lesson is incomplete if it leaves readers only with a diagram and no attention to worship, prayer, and obedient teaching. The commission includes observing what Jesus commanded. A group may therefore examine whether its teaching cultivates the life to which the passage calls it.","sourceIds":["matthew","nicene","ccc-creeds"],"locator":"Matthew 28:19–20; OCA Nicene text; Catechism 195; editorial scope","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-4-2","text":"Differences about the procession of the Spirit and the later Western addition to the creed require historical precision. This preview does not silently choose one wording as though every church uses it. Before local adoption, a pastor should confirm the church’s received creed and preferred terminology. Honest identification of that decision makes shared learning possible.","sourceIds":["matthew","nicene","ccc-creeds"],"locator":"Matthew 28:19–20; OCA Nicene text; Catechism 195; editorial scope","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-5-1","text":"Invite learners to identify the difference between the biblical sentence and the doctrinal summary. Matthew supplies the baptismal naming of Father, Son, and Spirit within a commission. The Nicene formulation supplies a received way of confessing the divine unity and distinction. Both can be studied closely without pretending that their genres are identical. A helpful teaching session allows a learner to say which kind of statement is being made and why it matters.","sourceIds":["matthew","nicene"],"locator":"Matthew 28:19–20; Nicene confession; original teaching exercise","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"trinity-5-2","text":"If a question reaches beyond the lesson, record it rather than improvising an answer. Terms about eternal relations, procession, and the history of conciliar language deserve more than an analogy offered under pressure. Careful limits model reverence and give a pastor a clear starting point for further teaching.","sourceIds":["matthew","nicene"],"locator":"Matthew 28:19–20; Nicene confession; original teaching exercise","category":"D","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"comparison","title":"The confession’s boundaries","steps":["One God","Father, Son, Spirit distinguished","One divine being","Baptism, worship, discipleship"]}},"yhwh-yireh":{"id":"yhwh-yireh","part":3,"title":"YHWH-Yireh","subtitle":"The LORD Will Provide","summary":"A careful journey through Genesis 22: a named place, a threatened promise, a spared son, and the provision of a ram. Learn what this traditional divine title says—and what the narrative does not promise.","readingMinutes":17,"scripture":{"reference":"Genesis 22:13–14","text":"Abraham lifted up his eyes, and looked, and saw that behind him was a ram caught in the thicket by his horns. Abraham went and took the ram, and offered him up for a burnt offering instead of his son. Abraham called the name of that place “The LORD Will Provide”. As it is said to this day, “On the LORD’s mountain, it will be provided.”","context":"Read Genesis 22:1–19 in full. The narrator identifies the event as a test. God interrupts Abraham before Isaac is harmed, and the ram is offered instead of Isaac.","url":"https://ebible.org/engwebp/GEN22.htm"},"objectives":["Trace the narrative from test to provision without removing its ethical difficulty.","Distinguish the place name in Genesis 22:14 from a modern list of divine attributes.","Connect Christian reception in Hebrews and James to the original narrative while labeling interpretation.","Apply the passage without promising wealth or authorizing harm."],"essentialQuestions":["What is named in Genesis 22:14?","How does the provision of the ram relate to Isaac and the promise?","What limits should govern a modern application of this difficult narrative?"],"sections":[{"id":"yhwh-yireh-section-1","title":"Begin with the story, not the label","paragraphs":["YHWH-Yireh is a conventional transliteration used in Christian teaching for the expression associated with Genesis 22:14. The WEB main text reads “The LORD Will Provide” and its footnote also gives “the LORD Jireh” and “the LORD Seeing.” These renderings belong to a particular sentence in a story. They should not be turned into a secret formula or a detached technique for securing an outcome.","The verse explicitly says Abraham names the place. Devotional charts often place the expression alongside personal names and titles of God. That traditional use can help readers remember God’s provision, provided the distinction remains visible: in this passage it is the name given to a location, expressing Abraham’s interpretation of what has happened there. Calling it a traditional divine title should never erase its original literary function.","Read the chapter aloud before studying the title. Notice who speaks, when information is given, and what Abraham can or cannot see. The narrator tells the reader that God is testing Abraham at the outset. Abraham and Isaac travel without a narrated explanation of how the test will end. The difference between the reader’s knowledge and the characters’ experience is part of the story’s force."],"claimIds":["yhwh-yireh-1-1","yhwh-yireh-1-2","yhwh-yireh-1-3"]},{"id":"yhwh-yireh-section-2","title":"A promise placed under terrible pressure","paragraphs":["The account belongs within Abraham’s larger story. Genesis 12:1–3 presents a call with promises of blessing and a future reaching other families of the earth. Genesis 22:1–2 identifies Isaac as the beloved son whom Abraham is told to offer. The command creates a severe tension: the threatened child is also central to the promised future. Reading this merely as an example of being optimistic about money misses the actual conflict.","The text reports concrete actions—travel, wood, fire, a knife, an altar—and a conversation between father and son. Isaac asks about the missing lamb. Abraham answers that God will provide. The narrative does not give a complete transcript of Abraham’s thoughts or Isaac’s inner life. A teaching illustration may imagine expressions or landscape, but it must be labeled an artist’s interpretation. We should not fill the silence with invented facts.","Some details invite further study without supporting confident reconstruction. The land of Moriah is named, but the passage supplies no modern coordinates, exact route, or age for Isaac. A map should show the limits of the evidence. An illustration of an identifiable summit would communicate more certainty than this chapter alone permits. Textual care includes being willing to leave parts of a scene unresolved."],"claimIds":["yhwh-yireh-2-1","yhwh-yireh-2-2","yhwh-yireh-2-3"]},{"id":"yhwh-yireh-section-3","title":"The interruption and the ram","paragraphs":["At the decisive moment the LORD’s angel calls Abraham by name and forbids him to lay a hand on the boy or do anything to him. Abraham then sees a ram caught by its horns. He offers it instead of his son. The sequence matters: the story’s resolution is not the death of Isaac but the prevention of that death and the provision of an animal offering in his place.","The expression “instead of his son” gives the substitution in this episode a clear textual basis. Further claims about all sacrificial theology require further evidence. The ram is a ram in Genesis 22; replacing it in a supposedly verbatim retelling with a lamb would alter the text. Abraham’s earlier answer about a lamb and the later appearance of a ram should both remain visible to the reader.","Abraham’s naming of the place memorializes this provision. The chapter then reports a renewed promise expressed through the LORD’s angel and returns Abraham to Beersheba. Provision, obedience, promise, and remembrance belong within one narrative. The title can be taught well when it directs a group back to these events instead of replacing them with an attractive slogan."],"claimIds":["yhwh-yireh-3-1","yhwh-yireh-3-2","yhwh-yireh-3-3"]},{"id":"yhwh-yireh-section-4","title":"The ethical difficulty must stay in view","paragraphs":["A command concerning the sacrifice of a child is disturbing, and the lesson should not hurry readers past that response. The chapter identifies an exceptional test and records a direct interruption. It does not give parents, pastors, or political leaders a repeatable instruction. Elsewhere Deuteronomy explicitly rejects offering sons and daughters in fire. A Christian teacher must read the difficult narrative alongside that prohibition.","No reader should be told that harming a child proves faith or that obedience to a religious leader requires ignoring protection from violence. That conclusion is a pastoral safeguard informed by the prohibition and the story’s interruption, not a claim that the chapter is emotionally easy. A group leader should let readers name the difficulty and avoid making survivors of abuse defend their discomfort.","Faithful application can include trust, but “trust” needs careful definition. It is not surrendering moral responsibility to whoever claims to speak for God. The narrator’s account is not equivalent to an ordinary person’s private impression. Discernment involves Scripture, accountable community, and protection of those who could be harmed. The story must never become a tool for coercion."],"claimIds":["yhwh-yireh-4-1","yhwh-yireh-4-2","yhwh-yireh-4-3"]},{"id":"yhwh-yireh-section-5","title":"How later Christian texts receive Abraham","paragraphs":["Hebrews 11:17–19 interprets Abraham’s testing in relation to the promise and the conviction that God can raise the dead. The author presents Isaac’s recovery figuratively in that frame. This is a New Testament reading of Genesis, not a quotation from Genesis describing every step of Abraham’s reasoning. Naming the relationship between the two texts keeps Christian interpretation accountable.","James 2:21–23 refers to Abraham’s offering of Isaac while discussing faith and works. Its argument is that faith works with action and reaches completion through it. Read the surrounding paragraph, including its concern for people lacking clothing or food. Using Abraham only to win an abstract dispute while ignoring James’s concrete concern for a neighbor would distort the setting.","Christian preaching often relates the beloved son and the provided offering to Jesus. Romans 8:32 speaks of God giving his own Son, and Christian readers may see a meaningful connection. Label that connection as canonical or typological interpretation. Genesis 22 itself neither names Jesus nor provides a complete doctrine of the cross. A fruitful connection does not require treating every narrative detail as a coded prediction."],"claimIds":["yhwh-yireh-5-1","yhwh-yireh-5-2","yhwh-yireh-5-3"]},{"id":"yhwh-yireh-section-6","title":"Trusting provision without selling certainty","paragraphs":["The story supports remembrance of God’s provision in this event; it does not say that every faithful person will receive a requested job, recovery, house, or financial increase. Hebrews 11 itself includes faithful people who suffer and die. Romans 8 names anguish, famine, danger, and death while affirming the endurance of God’s love. These passages resist a simplistic prosperity reading.","A responsible devotional response might be gratitude for concrete help, willingness to receive help from a community, or patient prayer in an unresolved need. It should allow lament and should not blame someone whose situation remains painful. The difference between a testimony and a universal promise is crucial: “This is how I experienced provision” is a claim about an event; “God must do the same for you” requires a warrant this narrative does not give.","For group study, draw the story’s sequence and attach each conclusion to a verse. Mark the original event, later biblical reception, and present application in different columns. Finish by asking what practical care the community can offer to someone under pressure. That exercise turns a remembered title into attentive reading and compassionate action while keeping theological claims open to review."],"claimIds":["yhwh-yireh-6-1","yhwh-yireh-6-2","yhwh-yireh-6-3"]},{"id":"yhwh-yireh-section-7","title":"A reviewable conclusion","paragraphs":["The chapter’s title should now summon a whole reading rather than a fragment: an extraordinary test, a threatened child, an interrupted act, an offered ram, a named place, and a renewed promise. Its emotional difficulty remains part of that reading. The later uses of Abraham in Hebrews and James add identifiable canonical interpretation without giving permission to invent details in Genesis.","Before teaching the lesson, a reviewer can check four things. Does the quotation reproduce the selected WEB edition? Does the explanation distinguish a place name from devotional usage? Are later Christian connections labeled as interpretation? Does the application protect vulnerable people and avoid an unconditional guarantee of prosperity? These questions make the material reviewable without pretending that a completed checklist confers ecclesial approval. The lesson is an invitation to careful study and pastoral judgment."],"claimIds":["yhwh-yireh-7-1","yhwh-yireh-7-2"]}],"languageNote":{"term":"YHWH-Yireh","transliteration":"Also commonly written Yahweh Yireh or Jehovah Jireh","meaning":"Traditional label associated with the place Abraham names in Genesis 22:14. WEB: “The LORD Will Provide”; its note includes “the LORD Seeing.”","caution":"Transliteration varies. This is a contextual translation note, not an independently completed Hebrew grammatical analysis. No popular etymology or pronunciation claim is required for the lesson.","sourceUrl":"https://ebible.org/engwebp/GEN22.htm"},"relatedPassages":[{"reference":"Genesis 12:1–3","url":"https://ebible.org/engwebp/GEN12.htm"},{"reference":"Hebrews 11:17–19","url":"https://ebible.org/engwebp/HEB11.htm"},{"reference":"James 2:21–23","url":"https://ebible.org/engwebp/JAS02.htm"},{"reference":"Romans 8:31–39","url":"https://ebible.org/engwebp/ROM08.htm"},{"reference":"Deuteronomy 12:29–31","url":"https://ebible.org/engwebp/DEU12.htm"}],"consensus":"For this Nicene educational preview, God’s goodness and trustworthiness govern application. The textual observations that the boy is spared and a ram is offered instead of him are directly stated in Genesis 22:12–13.","disputed":"The relation of this test to divine knowledge, the historical location of Moriah, and the scope of Christian typology require further specialist and pastoral review. This lesson does not certify one solution or a precise map location.","application":["Name a concrete provision with gratitude while allowing another person’s unanswered prayer to remain painful.","Offer practical help to someone in need; avoid treating “God will provide” as permission to withhold assistance.","Read the chapter with safeguards: no contemporary claim of revelation authorizes violence against a child."],"reflection":["Do I remember the actual passage when I use this title?","Have I mistaken a testimony for a guarantee?","What part of the narrative remains difficult for me?"],"discussion":["Why does it matter that Abraham names a place?","Compare the uses of Abraham in Hebrews 11 and James 2.","How can a group speak of provision while caring for people living with loss?"],"quiz":[{"question":"What does Abraham name in Genesis 22:14?","options":["The ram","The place","A new tribal group"],"answer":1,"explanation":"The verse explicitly identifies the place as what Abraham names. Its use as a divine title is a later devotional convention."},{"question":"What is offered instead of Isaac?","options":["A ram caught in a thicket","A lamb brought from Beersheba","Nothing; the narrative ends before an offering"],"answer":0,"explanation":"Genesis 22:13 identifies a ram and states that Abraham offered it instead of his son."},{"question":"Which application stays within responsible limits?","options":["Faith guarantees every desired financial outcome","A private impression can authorize harm","Remember God’s provision while caring practically for people in need"],"answer":2,"explanation":"The narrative is not an unconditional prosperity promise or a repeatable authorization for violence."}],"sources":[{"id":"genesis22","title":"World English Bible (Updated): Genesis 22:1–19 and footnote 22:14","url":"https://ebible.org/engwebp/GEN22.htm","locator":"Genesis 22:1–19 and footnote 22:14","category":"A"},{"id":"genesis12","title":"World English Bible (Updated): Genesis 12:1–3","url":"https://ebible.org/engwebp/GEN12.htm","locator":"Genesis 12:1–3","category":"A"},{"id":"hebrews11","title":"World English Bible (Updated): Hebrews 11:17–19, 35–40","url":"https://ebible.org/engwebp/HEB11.htm","locator":"Hebrews 11:17–19, 35–40","category":"A"},{"id":"james2","title":"World English Bible (Updated): James 2:14–26","url":"https://ebible.org/engwebp/JAS02.htm","locator":"James 2:14–26","category":"A"},{"id":"romans8","title":"World English Bible (Updated): Romans 8:31–39","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:31–39","category":"A"},{"id":"deuteronomy12","title":"World English Bible (Updated): Deuteronomy 12:29–31","url":"https://ebible.org/engwebp/DEU12.htm","locator":"Deuteronomy 12:29–31","category":"A"}],"claims":[{"id":"yhwh-yireh-1-1","text":"YHWH-Yireh is a conventional transliteration used in Christian teaching for the expression associated with Genesis 22:14. The WEB main text reads “The LORD Will Provide” and its footnote also gives “the LORD Jireh” and “the LORD Seeing.” These renderings belong to a particular sentence in a story. They should not be turned into a secret formula or a detached technique for securing an outcome.","sourceIds":["genesis22"],"locator":"Genesis 22:1–14; WEB footnote to 22:14","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-1-2","text":"The verse explicitly says Abraham names the place. Devotional charts often place the expression alongside personal names and titles of God. That traditional use can help readers remember God’s provision, provided the distinction remains visible: in this passage it is the name given to a location, expressing Abraham’s interpretation of what has happened there. Calling it a traditional divine title should never erase its original literary function.","sourceIds":["genesis22"],"locator":"Genesis 22:1–14; WEB footnote to 22:14","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-1-3","text":"Read the chapter aloud before studying the title. Notice who speaks, when information is given, and what Abraham can or cannot see. The narrator tells the reader that God is testing Abraham at the outset. Abraham and Isaac travel without a narrated explanation of how the test will end. The difference between the reader’s knowledge and the characters’ experience is part of the story’s force.","sourceIds":["genesis22"],"locator":"Genesis 22:1–14; WEB footnote to 22:14","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-2-1","text":"The account belongs within Abraham’s larger story. Genesis 12:1–3 presents a call with promises of blessing and a future reaching other families of the earth. Genesis 22:1–2 identifies Isaac as the beloved son whom Abraham is told to offer. The command creates a severe tension: the threatened child is also central to the promised future. Reading this merely as an example of being optimistic about money misses the actual conflict.","sourceIds":["genesis22","genesis12"],"locator":"Genesis 12:1–3; 22:1–10; geographical and psychological limits noted","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-2-2","text":"The text reports concrete actions—travel, wood, fire, a knife, an altar—and a conversation between father and son. Isaac asks about the missing lamb. Abraham answers that God will provide. The narrative does not give a complete transcript of Abraham’s thoughts or Isaac’s inner life. A teaching illustration may imagine expressions or landscape, but it must be labeled an artist’s interpretation. We should not fill the silence with invented facts.","sourceIds":["genesis22","genesis12"],"locator":"Genesis 12:1–3; 22:1–10; geographical and psychological limits noted","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-2-3","text":"Some details invite further study without supporting confident reconstruction. The land of Moriah is named, but the passage supplies no modern coordinates, exact route, or age for Isaac. A map should show the limits of the evidence. An illustration of an identifiable summit would communicate more certainty than this chapter alone permits. Textual care includes being willing to leave parts of a scene unresolved.","sourceIds":["genesis22","genesis12"],"locator":"Genesis 12:1–3; 22:1–10; geographical and psychological limits noted","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-3-1","text":"At the decisive moment the LORD’s angel calls Abraham by name and forbids him to lay a hand on the boy or do anything to him. Abraham then sees a ram caught by its horns. He offers it instead of his son. The sequence matters: the story’s resolution is not the death of Isaac but the prevention of that death and the provision of an animal offering in his place.","sourceIds":["genesis22"],"locator":"Genesis 22:7–19","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-3-2","text":"The expression “instead of his son” gives the substitution in this episode a clear textual basis. Further claims about all sacrificial theology require further evidence. The ram is a ram in Genesis 22; replacing it in a supposedly verbatim retelling with a lamb would alter the text. Abraham’s earlier answer about a lamb and the later appearance of a ram should both remain visible to the reader.","sourceIds":["genesis22"],"locator":"Genesis 22:7–19","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-3-3","text":"Abraham’s naming of the place memorializes this provision. The chapter then reports a renewed promise expressed through the LORD’s angel and returns Abraham to Beersheba. Provision, obedience, promise, and remembrance belong within one narrative. The title can be taught well when it directs a group back to these events instead of replacing them with an attractive slogan.","sourceIds":["genesis22"],"locator":"Genesis 22:7–19","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-4-1","text":"A command concerning the sacrifice of a child is disturbing, and the lesson should not hurry readers past that response. The chapter identifies an exceptional test and records a direct interruption. It does not give parents, pastors, or political leaders a repeatable instruction. Elsewhere Deuteronomy explicitly rejects offering sons and daughters in fire. A Christian teacher must read the difficult narrative alongside that prohibition.","sourceIds":["genesis22","deuteronomy12"],"locator":"Genesis 22:1, 11–13; Deuteronomy 12:29–31; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-4-2","text":"No reader should be told that harming a child proves faith or that obedience to a religious leader requires ignoring protection from violence. That conclusion is a pastoral safeguard informed by the prohibition and the story’s interruption, not a claim that the chapter is emotionally easy. A group leader should let readers name the difficulty and avoid making survivors of abuse defend their discomfort.","sourceIds":["genesis22","deuteronomy12"],"locator":"Genesis 22:1, 11–13; Deuteronomy 12:29–31; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-4-3","text":"Faithful application can include trust, but “trust” needs careful definition. It is not surrendering moral responsibility to whoever claims to speak for God. The narrator’s account is not equivalent to an ordinary person’s private impression. Discernment involves Scripture, accountable community, and protection of those who could be harmed. The story must never become a tool for coercion.","sourceIds":["genesis22","deuteronomy12"],"locator":"Genesis 22:1, 11–13; Deuteronomy 12:29–31; explicitly pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-5-1","text":"Hebrews 11:17–19 interprets Abraham’s testing in relation to the promise and the conviction that God can raise the dead. The author presents Isaac’s recovery figuratively in that frame. This is a New Testament reading of Genesis, not a quotation from Genesis describing every step of Abraham’s reasoning. Naming the relationship between the two texts keeps Christian interpretation accountable.","sourceIds":["hebrews11","james2","romans8","genesis22"],"locator":"Hebrews 11:17–19; James 2:14–26; Romans 8:31–39; Christian canonical interpretation","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-5-2","text":"James 2:21–23 refers to Abraham’s offering of Isaac while discussing faith and works. Its argument is that faith works with action and reaches completion through it. Read the surrounding paragraph, including its concern for people lacking clothing or food. Using Abraham only to win an abstract dispute while ignoring James’s concrete concern for a neighbor would distort the setting.","sourceIds":["hebrews11","james2","romans8","genesis22"],"locator":"Hebrews 11:17–19; James 2:14–26; Romans 8:31–39; Christian canonical interpretation","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-5-3","text":"Christian preaching often relates the beloved son and the provided offering to Jesus. Romans 8:32 speaks of God giving his own Son, and Christian readers may see a meaningful connection. Label that connection as canonical or typological interpretation. Genesis 22 itself neither names Jesus nor provides a complete doctrine of the cross. A fruitful connection does not require treating every narrative detail as a coded prediction.","sourceIds":["hebrews11","james2","romans8","genesis22"],"locator":"Hebrews 11:17–19; James 2:14–26; Romans 8:31–39; Christian canonical interpretation","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-6-1","text":"The story supports remembrance of God’s provision in this event; it does not say that every faithful person will receive a requested job, recovery, house, or financial increase. Hebrews 11 itself includes faithful people who suffer and die. Romans 8 names anguish, famine, danger, and death while affirming the endurance of God’s love. These passages resist a simplistic prosperity reading.","sourceIds":["genesis22","hebrews11","romans8","james2"],"locator":"Genesis 22:13–19; Hebrews 11:35–40; Romans 8:35–39; James 2:15–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-6-2","text":"A responsible devotional response might be gratitude for concrete help, willingness to receive help from a community, or patient prayer in an unresolved need. It should allow lament and should not blame someone whose situation remains painful. The difference between a testimony and a universal promise is crucial: “This is how I experienced provision” is a claim about an event; “God must do the same for you” requires a warrant this narrative does not give.","sourceIds":["genesis22","hebrews11","romans8","james2"],"locator":"Genesis 22:13–19; Hebrews 11:35–40; Romans 8:35–39; James 2:15–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-6-3","text":"For group study, draw the story’s sequence and attach each conclusion to a verse. Mark the original event, later biblical reception, and present application in different columns. Finish by asking what practical care the community can offer to someone under pressure. That exercise turns a remembered title into attentive reading and compassionate action while keeping theological claims open to review.","sourceIds":["genesis22","hebrews11","romans8","james2"],"locator":"Genesis 22:13–19; Hebrews 11:35–40; Romans 8:35–39; James 2:15–17; pastoral application","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-7-1","text":"The chapter’s title should now summon a whole reading rather than a fragment: an extraordinary test, a threatened child, an interrupted act, an offered ram, a named place, and a renewed promise. Its emotional difficulty remains part of that reading. The later uses of Abraham in Hebrews and James add identifiable canonical interpretation without giving permission to invent details in Genesis.","sourceIds":["genesis22","hebrews11","james2"],"locator":"Genesis 22:1–19; Hebrews 11:17–19; James 2:21–23; editorial synthesis","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."},{"id":"yhwh-yireh-7-2","text":"Before teaching the lesson, a reviewer can check four things. Does the quotation reproduce the selected WEB edition? Does the explanation distinguish a place name from devotional usage? Are later Christian connections labeled as interpretation? Does the application protect vulnerable people and avoid an unconditional guarantee of prosperity? These questions make the material reviewable without pretending that a completed checklist confers ecclesial approval. The lesson is an invitation to careful study and pastoral judgment.","sourceIds":["genesis22","hebrews11","james2"],"locator":"Genesis 22:1–19; Hebrews 11:17–19; James 2:21–23; editorial synthesis","category":"A","verification":"references-checked","uncertainty":"Editorial explanation of the cited evidence; pastoral review pending."}],"status":"references-checked","diagram":{"type":"sequence","title":"Read the narrative in order","steps":["The test · 22:1–2","The question · 22:7–8","The interruption · 22:11–12","The provision · 22:13–14"]}}};
export const REFERENCES_DATA: any = {"bibliography":[{"id":"luke","title":"World English Bible (Updated): Luke 24:13–35","url":"https://ebible.org/engwebp/LUK24.htm","locator":"Luke 24:13–35","category":"A"},{"id":"ccc-creeds","title":"Catechism of the Catholic Church: The Creeds","url":"https://www.vatican.va/archive/ENG0015/__P14.HTM","locator":"185–196","category":"E"},{"id":"timothy","title":"World English Bible (Updated): 2 Timothy 3:10–17","url":"https://ebible.org/engwebp/2TI03.htm","locator":"2 Timothy 3:10–17","category":"A"},{"id":"bfm","title":"Southern Baptist Convention: Baptist Faith and Message 2000","url":"https://bfm.sbc.net/bfm2000/","locator":"Articles I–VII and X","category":"E"},{"id":"wcf","title":"Westminster Confession of Faith, Orthodox Presbyterian Church edition","url":"https://www.opc.org/wcf.html","locator":"Chapters I–III, VI, XI, XXV, XXVIII, XXXII–XXXIII","category":"E"},{"id":"genesis22","title":"World English Bible (Updated): Genesis 22:1–19 and footnote 22:14","url":"https://ebible.org/engwebp/GEN22.htm","locator":"Genesis 22:1–19 and footnote 22:14","category":"A"},{"id":"genesis12","title":"World English Bible (Updated): Genesis 12:1–3","url":"https://ebible.org/engwebp/GEN12.htm","locator":"Genesis 12:1–3","category":"A"},{"id":"hebrews11","title":"World English Bible (Updated): Hebrews 11:17–19, 35–40","url":"https://ebible.org/engwebp/HEB11.htm","locator":"Hebrews 11:17–19, 35–40","category":"A"},{"id":"james2","title":"World English Bible (Updated): James 2:14–26","url":"https://ebible.org/engwebp/JAS02.htm","locator":"James 2:14–26","category":"A"},{"id":"romans8","title":"World English Bible (Updated): Romans 8:31–39","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:31–39","category":"A"},{"id":"deuteronomy12","title":"World English Bible (Updated): Deuteronomy 12:29–31","url":"https://ebible.org/engwebp/DEU12.htm","locator":"Deuteronomy 12:29–31","category":"A"},{"id":"psalm","title":"World English Bible (Updated): Psalms 139:1–24","url":"https://ebible.org/engwebp/PSA139.htm","locator":"Psalms 139:1–24","category":"A"},{"id":"john","title":"World English Bible (Updated): 1 John 3:16–24","url":"https://ebible.org/engwebp/1JN03.htm","locator":"1 John 3:16–24","category":"A"},{"id":"matthew","title":"World English Bible (Updated): Matthew 28:16–20","url":"https://ebible.org/engwebp/MAT28.htm","locator":"Matthew 28:16–20","category":"A"},{"id":"john","title":"World English Bible (Updated): John 17:1–5","url":"https://ebible.org/engwebp/JHN17.htm","locator":"John 17:1–5","category":"A"},{"id":"nicene","title":"Nicene-Constantinopolitan Creed, Orthodox Church in America presentation","url":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed","locator":"The Symbol of Faith: Nicene Creed; councils of 325 and 381","category":"D"},{"id":"creation","title":"World English Bible (Updated): Genesis 1:1–31","url":"https://ebible.org/engwebp/GEN01.htm","locator":"Genesis 1:1–31","category":"A"},{"id":"noah","title":"World English Bible (Updated): Genesis 9:8–17","url":"https://ebible.org/engwebp/GEN09.htm","locator":"Genesis 9:8–17","category":"A"},{"id":"colossians","title":"World English Bible (Updated): Colossians 1:15–20","url":"https://ebible.org/engwebp/COL01.htm","locator":"Colossians 1:15–20","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 8:18–25","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:18–25","category":"A"},{"id":"genesis","title":"World English Bible (Updated): Genesis 1:26–31","url":"https://ebible.org/engwebp/GEN01.htm","locator":"Genesis 1:26–31","category":"A"},{"id":"noah","title":"World English Bible (Updated): Genesis 9:5–7","url":"https://ebible.org/engwebp/GEN09.htm","locator":"Genesis 9:5–7","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 5:1–21","url":"https://ebible.org/engwebp/ROM05.htm","locator":"Romans 5:1–21","category":"A"},{"id":"john6","title":"World English Bible (Updated): John 6:1–71","url":"https://ebible.org/engwebp/JHN06.htm","locator":"John 6:1–71","category":"A"},{"id":"james","title":"World English Bible (Updated): James 2:14–17","url":"https://ebible.org/engwebp/JAS02.htm","locator":"James 2:14–17","category":"A"},{"id":"ccc-initiation","title":"Catechism of the Catholic Church: Christian Initiation","url":"https://www.vatican.va/archive/ENG0015/__P3O.HTM","locator":"1275–1284, especially 1275","category":"E"},{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 12:1–26","url":"https://ebible.org/engwebp/1CO12.htm","locator":"1 Corinthians 12:1–26","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 8:14–27","url":"https://ebible.org/engwebp/ROM08.htm","locator":"Romans 8:14–27","category":"A"},{"id":"ephesians","title":"World English Bible (Updated): Ephesians 2:1–22","url":"https://ebible.org/engwebp/EPH02.htm","locator":"Ephesians 2:1–22","category":"A"},{"id":"romans","title":"World English Bible (Updated): Romans 5:1–11","url":"https://ebible.org/engwebp/ROM05.htm","locator":"Romans 5:1–11","category":"A"},{"id":"ccc-grace","title":"Catechism of the Catholic Church: Justification","url":"https://www.vatican.va/archive/ENG0015/__P6Y.HTM","locator":"1987–1995","category":"E"},{"id":"hebrews","title":"World English Bible (Updated): Hebrews 1:1–14","url":"https://ebible.org/engwebp/HEB01.htm","locator":"Hebrews 1:1–14","category":"A"},{"id":"acts","title":"World English Bible (Updated): Acts 2:22–47","url":"https://ebible.org/engwebp/ACT02.htm","locator":"Acts 2:22–47","category":"A"},{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 12:12–26","url":"https://ebible.org/engwebp/1CO12.htm","locator":"1 Corinthians 12:12–26","category":"A"},{"id":"ephesians","title":"World English Bible (Updated): Ephesians 2:19–22","url":"https://ebible.org/engwebp/EPH02.htm","locator":"Ephesians 2:19–22","category":"A"},{"id":"ccc-initiation","title":"Catechism: Christian Initiation","url":"https://www.vatican.va/archive/ENG0015/__P3O.HTM","locator":"1275–1284","category":"E"},{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 15:1–58","url":"https://ebible.org/engwebp/1CO15.htm","locator":"1 Corinthians 15:1–58","category":"A"},{"id":"matthew","title":"World English Bible (Updated): Matthew 22:34–40","url":"https://ebible.org/engwebp/MAT22.htm","locator":"Matthew 22:34–40","category":"A"},{"id":"john","title":"World English Bible (Updated): 1 John 3:16–18","url":"https://ebible.org/engwebp/1JN03.htm","locator":"1 John 3:16–18","category":"A"},{"id":"corinthians","title":"World English Bible (Updated): 1 Corinthians 15:1–11","url":"https://ebible.org/engwebp/1CO15.htm","locator":"1 Corinthians 15:1–11","category":"A"}],"words":[{"lessonId":"interpreting-scripture","lessonTitle":"Learning to Read Scripture Well","term":"Interpretation","transliteration":"Study vocabulary","meaning":"An explanation of how a passage communicates meaning in its context.","caution":"This English definition is a study aid, not a Hebrew or Greek etymology.","sourceUrl":"https://ebible.org/engwebp/LUK24.htm"},{"lessonId":"scripture","lessonTitle":"The Doctrine of Scripture","term":"God-breathed","transliteration":"WEB translation wording","meaning":"The WEB’s rendering in 2 Timothy 3:16 describes Scripture’s relation to God.","caution":"The WEB footnote records an alternative construction. No conclusion about canon or translation perfection follows from the English phrase alone.","sourceUrl":"https://ebible.org/engwebp/2TI03.htm"},{"lessonId":"yhwh-yireh","lessonTitle":"YHWH-Yireh","term":"YHWH-Yireh","transliteration":"Also commonly written Yahweh Yireh or Jehovah Jireh","meaning":"Traditional label associated with the place Abraham names in Genesis 22:14. WEB: “The LORD Will Provide”; its note includes “the LORD Seeing.”","caution":"Transliteration varies. This is a contextual translation note, not an independently completed Hebrew grammatical analysis. No popular etymology or pronunciation claim is required for the lesson.","sourceUrl":"https://ebible.org/engwebp/GEN22.htm"},{"lessonId":"omniscience","lessonTitle":"Known Completely by God","term":"Omniscience","transliteration":"English theological vocabulary","meaning":"A doctrinal label for the completeness of divine knowledge.","caution":"The term is a later theological label, not the original-language wording of Psalm 139. The lesson does not derive a philosophical system from an alleged Hebrew root.","sourceUrl":"https://ebible.org/engwebp/PSA139.htm"},{"lessonId":"trinity","lessonTitle":"One God: Father, Son, and Holy Spirit","term":"Trinity","transliteration":"Later Christian doctrinal terminology","meaning":"A theological name for the confession of the one God as Father, Son, and Holy Spirit.","caution":"The English word is not a quotation from Matthew 28. It names a doctrinal synthesis, not an independently verified Greek etymology.","sourceUrl":"https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-symbol-of-faith/nicene-creed"},{"lessonId":"creation-covenant","lessonTitle":"Creation, Covenant, and Providence","term":"Providence","transliteration":"English theological vocabulary","meaning":"God’s sustaining and governing care for creation.","caution":"This definition summarizes a doctrinal topic. It does not identify an original Hebrew word in Genesis 1 or disclose the purpose of an individual disaster.","sourceUrl":"https://www.opc.org/wcf.html"},{"lessonId":"image-of-god","lessonTitle":"Humanity in the Image of God","term":"Image of God","transliteration":"WEB wording in Genesis 1:27","meaning":"The phrase identifies a relation God gives humanity in creation.","caution":"The English phrase does not by itself settle all debates about capacities, embodiment, or representation. No unverified Hebrew etymology is offered.","sourceUrl":"https://ebible.org/engwebp/GEN01.htm"},{"lessonId":"sin-and-grace","lessonTitle":"Sin and the Need for Grace","term":"Hamartiology","transliteration":"Conventional theological label","meaning":"The doctrinal study of sin.","caution":"This label is not an etymological argument that reduces every biblical description of sin to “missing the mark.” Context and the full range of biblical language matter.","sourceUrl":"https://ebible.org/engwebp/ROM05.htm"},{"lessonId":"bread-of-life","lessonTitle":"Jesus, the Bread of Life","term":"Bread of Life","transliteration":"WEB title in John 6:35","meaning":"A metaphorical self-identification of Jesus within a discourse about receiving life from him.","caution":"This is a contextual explanation, not an argument from an isolated Greek word. Eucharistic interpretations require the whole discourse and an identified theological framework.","sourceUrl":"https://ebible.org/engwebp/JHN06.htm"},{"lessonId":"holy-spirit","lessonTitle":"The Holy Spirit and the Common Good","term":"Pneumatology","transliteration":"Conventional theological label","meaning":"The doctrinal study of the Holy Spirit.","caution":"The label is not proof that every occurrence of “spirit” means the same thing. Context is needed; no isolated Greek root is used to authenticate a contemporary claim.","sourceUrl":"https://ebible.org/engwebp/1CO12.htm"},{"lessonId":"salvation","lessonTitle":"Salvation: Grace, Faith, and New Life","term":"Soteriology","transliteration":"Conventional theological label","meaning":"The doctrinal study of salvation and redemption.","caution":"The label does not replace the varied biblical images or settle disputed definitions of justification. No word study is offered as a shortcut around the chapter.","sourceUrl":"https://ebible.org/engwebp/EPH02.htm"},{"lessonId":"angels","lessonTitle":"Angels and Spiritual Beings","term":"Angelology","transliteration":"Conventional theological label","meaning":"The doctrinal study of angels and related biblical testimony about spiritual beings.","caution":"A theological label supplies no warrant for a detailed hierarchy. This lesson makes no claim about a Greek word’s meaning apart from the passage’s context.","sourceUrl":"https://ebible.org/engwebp/HEB01.htm"},{"lessonId":"church","lessonTitle":"The Church: A People Learning Life Together","term":"Ecclesiology","transliteration":"Conventional theological label","meaning":"The doctrinal study of the church and its life.","caution":"The lesson does not infer a complete form of church government from an isolated word. Narrative, letters, and identified traditions all require contextual reading.","sourceUrl":"https://ebible.org/engwebp/ACT02.htm"},{"lessonId":"resurrection-hope","lessonTitle":"Resurrection and Christian Hope","term":"Eschatology","transliteration":"Conventional theological label","meaning":"The doctrinal study of last things, including resurrection, judgment, and the consummation of hope.","caution":"A label does not establish a prophetic timetable. This lesson does not infer dates or certify one complete end-times system.","sourceUrl":"https://ebible.org/engwebp/1CO15.htm"},{"lessonId":"discipleship","lessonTitle":"Love of God and Love of Neighbor","term":"Discipleship","transliteration":"English study vocabulary","meaning":"Learning and practicing a life shaped by following Jesus.","caution":"No claim is made that a single Greek word determines every modern ministry method. The passage’s actual commands remain the starting point.","sourceUrl":"https://ebible.org/engwebp/MAT22.htm"},{"lessonId":"creeds","lessonTitle":"Creeds and the Memory of Christian Faith","term":"Creed","transliteration":"Latin credo is identified in the cited church sources","meaning":"A concise confession or profession of faith.","caution":"The term names a historical genre. A creed’s reception and authority must be stated for the community using it; no local approval is implied.","sourceUrl":"https://www.vatican.va/archive/ENG0015/__P14.HTM"}]};
export const ATLAS_CATALOG: any[] = [{"id":"interpreting-scripture","part":1,"title":"Learning to Read Scripture Well","subtitle":"Observation, context, interpretation, and faithful response","summary":"A practical introduction to theology that reads passages in their literary setting, distinguishes observation from inference, and brings questions to a learning community.","readingMinutes":9,"status":"references-checked","scriptureReference":"Luke 24:27"},{"id":"scripture","part":2,"title":"The Doctrine of Scripture","subtitle":"God-breathed writings that form a faithful people","summary":"Read 2 Timothy’s teaching about Scripture in its pastoral setting, with care for inspiration, purpose, canon, and the distinction between text and interpretation.","readingMinutes":10,"status":"references-checked","scriptureReference":"2 Timothy 3:16–17"},{"id":"yhwh-yireh","part":3,"title":"YHWH-Yireh","subtitle":"The LORD Will Provide","summary":"A careful journey through Genesis 22: a named place, a threatened promise, a spared son, and the provision of a ram. Learn what this traditional divine title says—and what the narrative does not promise.","readingMinutes":17,"status":"references-checked","scriptureReference":"Genesis 22:13–14"},{"id":"omniscience","part":3,"title":"Known Completely by God","subtitle":"Omniscience, prayer, and the searching love of God","summary":"Psalm 139 approaches divine knowledge through prayer rather than an abstract inventory of information. Learn to distinguish the psalm’s witness from later philosophical models.","readingMinutes":10,"status":"references-checked","scriptureReference":"Psalms 139:1–4"},{"id":"trinity","part":4,"title":"One God: Father, Son, and Holy Spirit","subtitle":"Learning the grammar of Nicene confession","summary":"The baptismal commission and the Nicene tradition teach Christians to confess one God while distinguishing Father, Son, and Holy Spirit. Simple analogies require care.","readingMinutes":9,"status":"references-checked","scriptureReference":"Matthew 28:18–20"},{"id":"creation-covenant","part":5,"title":"Creation, Covenant, and Providence","subtitle":"A good world sustained by a faithful Creator","summary":"Genesis’s account of creation and the covenant with Noah provide a framework for gratitude, responsibility, and hope without making every event easy to explain.","readingMinutes":9,"status":"references-checked","scriptureReference":"Genesis 1:1–2"},{"id":"image-of-god","part":6,"title":"Humanity in the Image of God","subtitle":"Dignity received, responsibility shared","summary":"Genesis locates human dignity in relation to God, not in achievement, social standing, or independence. The image language also gives humanity a responsibility within creation.","readingMinutes":8,"status":"references-checked","scriptureReference":"Genesis 1:27"},{"id":"sin-and-grace","part":7,"title":"Sin and the Need for Grace","subtitle":"Facing a broken condition without losing sight of mercy","summary":"Romans 5 places the reach of sin and death beside the greater gift in Christ. Learn to name personal and shared wrong without turning doctrine into shame or fatalism.","readingMinutes":9,"status":"references-checked","scriptureReference":"Romans 5:8"},{"id":"bread-of-life","part":8,"title":"Jesus, the Bread of Life","subtitle":"The sign points beyond the meal to the giver of life","summary":"John 6 moves from a shared meal to a demanding conversation about Jesus’ identity, faith, flesh, and life. Read the discourse as a whole and identify sacramental differences fairly.","readingMinutes":12,"status":"references-checked","scriptureReference":"John 6:35"},{"id":"holy-spirit","part":9,"title":"The Holy Spirit and the Common Good","subtitle":"Many gifts, one body, a life of love","summary":"Paul addresses spiritual gifts within a community that needs unity, mutual dependence, and care. The lesson distinguishes the biblical list from disputed accounts of gifts today.","readingMinutes":9,"status":"references-checked","scriptureReference":"1 Corinthians 12:4–7"},{"id":"salvation","part":10,"title":"Salvation: Grace, Faith, and New Life","subtitle":"Received as gift, lived in a renewed community","summary":"Ephesians 2 holds together God’s mercy, salvation by grace through faith, a life of good works, and the reconciliation of a divided people. Confessional differences remain visible.","readingMinutes":12,"status":"references-checked","scriptureReference":"Ephesians 2:8–10"},{"id":"angels","part":11,"title":"Angels and Spiritual Beings","subtitle":"Attending to Scripture without building a speculative system","summary":"Hebrews places angels in relation to the Son and describes their service. A responsible introduction keeps the focus on Christ and distinguishes biblical witness from later art and speculation.","readingMinutes":8,"status":"references-checked","scriptureReference":"Hebrews 1:14"},{"id":"church","part":12,"title":"The Church: A People Learning Life Together","subtitle":"Teaching, fellowship, bread, prayer, and care","summary":"Acts 2 portrays a community formed around apostolic teaching and shared life. The narrative offers a rich starting point while leaving later questions of polity and sacramental practice for identified traditions.","readingMinutes":9,"status":"references-checked","scriptureReference":"Acts 2:42"},{"id":"resurrection-hope","part":13,"title":"Resurrection and Christian Hope","subtitle":"A future that gives present labor meaning","summary":"First Corinthians 15 places future resurrection within the proclamation of Christ’s resurrection. Its conclusion directs hope toward steadfast work rather than speculative date-setting.","readingMinutes":9,"status":"references-checked","scriptureReference":"1 Corinthians 15:20"},{"id":"discipleship","part":14,"title":"Love of God and Love of Neighbor","subtitle":"Doctrine becoming a practiced way of life","summary":"Jesus’ answer about the greatest commandment joins devotion to God with love of neighbor. Christian ethics requires concrete discernment rather than a vague appeal to sincerity.","readingMinutes":8,"status":"references-checked","scriptureReference":"Matthew 22:39–40"},{"id":"creeds","part":15,"title":"Creeds and the Memory of Christian Faith","subtitle":"Receiving a confession while reading history carefully","summary":"Early confessional patterns and later creeds help communities teach and remember their faith. Historical context and denominational reception must remain distinct from the biblical text.","readingMinutes":9,"status":"references-checked","scriptureReference":"1 Corinthians 15:3–4"}];
